window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[149]={"id":"149","numero":149,"titre":"Angines (Amygdalite aiguë)","objectifs":[{"id":"149-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d'une angine","contenu":"<div class=\"obj-callout success\"><strong>Définition.</strong> L'<span class=\"kw-def\">angine</span> (ou <span class=\"kw-def\">amygdalite aiguë</span>) est une <span class=\"kw-def\">inflammation aiguë des amygdales palatines</span> (tonsilles palatines), voire de l'ensemble du <span class=\"kw-def\">pharynx</span>. Elle s'intègre dans la pathologie de l'<span class=\"kw-def\">anneau lymphatique de Waldeyer</span>, disposé à l'entrée des voies aéro-digestives supérieures.</div>\n\n      <p>Le <strong>syndrome « angine »</strong> associe :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Fièvre</span></li>\n        <li><span class=\"kw-clinique\">Odynophagie</span> (gêne douloureuse à la déglutition)</li>\n        <li><span class=\"kw-clinique\">Inflammation de l'oropharynx</span> à l'examen</li>\n        <li>± <span class=\"kw-clinique\">Otalgie réflexe</span></li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Discriminant clé.</strong> <span class=\"kw-alerte\">Pas de rhinite associée</span> — c'est ce qui distingue l'angine de la <span class=\"kw-def\">rhinopharyngite</span> (qui, elle, comporte une rhinorrhée). L'installation des symptômes est <strong>rapide</strong>.</div>\n\n      <p>Sur le plan épidémiologique de contage : <span class=\"kw-chiffre\">5 %</span> de la population est <span class=\"kw-etio\">porteur sain de SBHA</span> (<span class=\"kw-etio\">streptocoque</span> β-hémolytique du groupe A). La contamination se fait par <span class=\"kw-etio\">voie aérienne</span> à partir d'un porteur sain ou malade ; <span class=\"kw-clinique\">les</span> <span class=\"kw-etio\">rapports oro-génitaux</span> sont en cause pour le <span class=\"kw-clinique\">gonocoque</span> et la syphilis.</p>","frequence":0},{"id":"149-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie des angines érythémateuses et érythématopultacées","contenu":"<div class=\"callout callout-info\"><strong>Message clé.</strong> <span class=\"kw-clinique\">Les</span> angines érythémateuses et érythématopultacées sont <strong>majoritairement virales</strong> à tout âge. Le <span class=\"kw-etio\">streptocoque du groupe A (SGA)</span> est la <strong>seule bactérie justifiant une <span class=\"kw-ttt\">antibiothérapie</span></strong>, et son pic d'<span class=\"kw-def\">incidence</span> est l'<strong>enfant d'âge scolaire</strong>.</div>\n\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Origine <span class=\"kw-etio\">virale</span></th><th>Origine SGA</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Enfant</span></td>\n            <td><span class=\"kw-chiffre\">70 %</span></td>\n            <td><span class=\"kw-chiffre\">25 – 40 %</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Adulte</span></td>\n            <td><span class=\"kw-chiffre\">90 %</span></td>\n            <td><span class=\"kw-chiffre\">10 – 25 %</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Tous âges confondus</span></td>\n            <td>—</td>\n            <td><span class=\"kw-chiffre\">≈ 20 %</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <ul>\n        <li><strong>Pic d'<span class=\"kw-def\">incidence</span> du SGA :</strong> <span class=\"kw-chiffre\">5 – 15 ans</span> (possible <span class=\"kw-chiffre\">dès 3 ans</span>, rare chez l'adulte).</li>\n        <li><strong>Saisonnalité du SGA :</strong> <span class=\"kw-etio\">hiver</span> et surtout <span class=\"kw-etio\">début de printemps</span> ; contexte d'<span class=\"kw-etio\">épidémie</span> ou de <span class=\"kw-etio\">contage</span>.</li>\n        <li><strong>Portage asymptomatique :</strong> <span class=\"kw-chiffre\">5 %</span> de la population est <span class=\"kw-etio\">porteur sain de SBHA</span>.</li>\n      </ul>","frequence":1},{"id":"149-3","rang":"A","rubrique":"Contenu multimédia","titre":"Photographies : angines érythémateuse et érythémato-pultacée","contenu":"<p>Sémiologie visuelle des deux aspects <span class=\"kw-clinique\">les</span> plus fréquents à l'examen de l'oropharynx :</p>\n\n      <table >\n        <thead><tr><th>Aspect</th><th>Description de l'oropharynx</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Angine érythémateuse</span><br><em>(aspect le plus fréquent)</em></td>\n            <td>Amygdales et pharynx <span class=\"kw-clinique\">congestifs</span> : <span class=\"kw-clinique\">rouge vif</span>, amygdales <span class=\"kw-clinique\">augmentées de volume</span>. <span class=\"kw-clinique\">Pas d'enduit</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Angine érythématopultacée</span><br><em>(succède souvent à la forme érythémateuse)</em></td>\n            <td>Amygdales <span class=\"kw-clinique\">congestives</span> recouvertes d'un <span class=\"kw-clinique\">enduit pultacé</span> ± abondant, <span class=\"kw-clinique\">gris-jaunâtre</span>, <span class=\"kw-clinique\">punctiforme ou en traînées</span> :<br>\n              <strong>Consistance :</strong> <span class=\"kw-clinique\">mince et friable</span>, <span class=\"kw-clinique\">facilement décollable</span><br>\n              <strong>Extension :</strong> <span class=\"kw-alerte\">ne déborde pas la surface amygdalienne</span> (≠ fausses membranes)\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège majeur.</strong> L'aspect de l'oropharynx <span class=\"kw-alerte\">n'est PAS prédictif</span> de l'origine <span class=\"kw-etio\">SGA</span> : une angine à SGA peut être <span class=\"kw-clinique\">érythémateuse</span>, <span class=\"kw-clinique\">érythématopultacée</span>, voire <span class=\"kw-clinique\">unilatérale</span> ou <span class=\"kw-clinique\">érosive</span>. <strong>Aucune donnée clinique ne permet d'affirmer l'origine <span class=\"kw-etio\">bactérienne</span></strong> → seul le <span class=\"kw-bio\">TDR</span> tranche.</div>\n\n      <!-- TODO Kevin : déposer une photographie clinique (angine érythémateuse + érythématopultacée) dans assets/images/149/ — aucune photo dans le dossier source ni dans IMAGERIE A CONNAITRE.pdf. -->","frequence":0},{"id":"149-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des angines érythémateuses et érythémato-pultacées","contenu":"<div class=\"obj-callout success\"><strong>Le <span class=\"kw-def\">diagnostic positif</span> d'angine est clinique.</strong> Il repose sur le <span class=\"kw-def\">syndrome angine</span> : <span class=\"kw-clinique\">fièvre</span> + <span class=\"kw-clinique\">odynophagie</span> + <span class=\"kw-clinique\">inflammation de l'oropharynx</span>, d'installation <strong>rapide</strong>.</div>\n\n      <h4 class=\"kw-def\">Signes d'accompagnement</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Otalgie réflexe</span> inconstante.</li>\n        <li><span class=\"kw-clinique\">Adénopathies cervicales satellites</span> sensibles : inconstantes mais fréquentes, elles évoquent une étiologie <span class=\"kw-etio\">bactérienne</span>.</li>\n        <li>Signes parfois révélateurs et variables selon l'agent et l'âge : <span class=\"kw-clinique\">éruption</span>, <span class=\"kw-clinique\">douleurs abdominales</span> (enfant), <span class=\"kw-clinique\">signes respiratoires</span> (rhinorrhée, <span class=\"kw-clinique\">toux</span>, enrouement).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Orientation clinique : SGA <span class=\"kw-bio\">vs</span> <span class=\"kw-etio\">viral</span> (valeur prédictive insuffisante)</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Angine à SGA</th><th>Angine <span class=\"kw-etio\">virale</span></th></tr></thead>\n        <tbody>\n          <tr><td>Âge</td><td>Pic <span class=\"kw-chiffre\">5 – 15 ans</span></td><td>Tout âge</td></tr>\n          <tr><td>Début</td><td><span class=\"kw-clinique\">Brusque</span></td><td>Progressif</td></tr>\n          <tr><td><span class=\"kw-clinique\">Fièvre</span></td><td><span class=\"kw-clinique\">Élevée</span> (<span class=\"kw-chiffre\">&gt; 38 °C</span>)</td><td>Variable</td></tr>\n          <tr><td>Signes pharyngés</td><td><span class=\"kw-clinique\">Odynophagie intense</span> ; <span class=\"kw-clinique\">érythème pharyngé intense</span> ; <span class=\"kw-clinique\">purpura du voile</span> ; exsudat</td><td><span class=\"kw-clinique\">Dysphagie</span> modérée ou absente</td></tr>\n          <tr><td>Signes négatifs / autres</td><td><span class=\"kw-alerte\">Absence de toux</span> ; douleurs abdominales, <span class=\"kw-clinique\">vomissements</span></td><td><span class=\"kw-clinique\">Toux</span>, coryza, enrouement, <span class=\"kw-clinique\">diarrhée</span>, myalgies, conjonctivite</td></tr>\n          <tr><td><span class=\"kw-clinique\">Éruption</span></td><td>Rash <span class=\"kw-clinique\">scarlatiniforme</span></td><td><span class=\"kw-clinique\">Éruption</span> <span class=\"kw-etio\">virale</span> évocatrice (ex. pieds-mains-bouche)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Le tableau le plus évocateur de SGA = <span class=\"kw-clinique\">début brusque</span> + <span class=\"kw-clinique\">fièvre élevée</span> + <span class=\"kw-alerte\">absence de toux</span> + <span class=\"kw-clinique\">adénopathies sensibles</span>. Mais aucun de ces signes n'est suffisant : c'est le <span class=\"kw-bio\">TDR</span> qui confirme.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 147 — <span class=\"kw-clinique\">Fièvre</span> aiguë</em></p>","frequence":5},{"id":"149-5","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies des angines érythémateuses et érythémato-pultacées","contenu":"<table >\n        <thead><tr><th>Famille</th><th>Agents</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Virus</span> <em>(majorité)</em></td>\n            <td><span class=\"kw-etio\">Adénovirus</span> ; <span class=\"kw-etio\">EBV</span> ; <span class=\"kw-etio\">VIH</span> (<span class=\"kw-clinique\">primo-infection</span>) ; <span class=\"kw-etio\">rhinovirus</span> ; <span class=\"kw-etio\">coronavirus</span> ; <span class=\"kw-etio\">VRS</span> ; <span class=\"kw-etio\">myxovirus influenzae et para-influenzae</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Bactéries</span></td>\n            <td>Principalement <span class=\"kw-etio\">streptocoque β-hémolytique du groupe A (SGA)</span><br>\n              Plus rares : <span class=\"kw-etio\">streptocoques B, C, F, G</span> ; <span class=\"kw-etio\">gonocoque</span> ; <span class=\"kw-etio\">Francisella tularensis</span> (tularémie)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Parasite</span></td>\n            <td><span class=\"kw-etio\">Toxoplasma gondii</span> (toxoplasmose)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>L'étiologie qui compte.</strong> Seul le <span class=\"kw-etio\">SGA</span> justifie une <span class=\"kw-ttt\">antibiothérapie</span> (risque de complications post-streptococciques). Le SGA peut être le premier signe d'une <span class=\"kw-def\">scarlatine</span>.</div>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Drapeau rouge</span>.</strong> Devant une angine érythémateuse/érythématopultacée avec <span class=\"kw-bio\">TDR négatif</span> + <span class=\"kw-def\">facteurs de risque</span>, penser à une <span class=\"kw-alerte\">primo-infection VIH</span> et proposer un <span class=\"kw-def\">dépistage</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":1},{"id":"149-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","contenu":"<div class=\"obj-callout success\"><strong>Pivot de l'item (objectif très tombé).</strong> Le diagnostic d'angine est clinique, mais aucune donnée clinique n'affirme l'origine <span class=\"kw-etio\">bactérienne</span> → le <span class=\"kw-bio\">test de diagnostic rapide (TDR)</span> du SGA est l'examen central qui guide l'<span class=\"kw-ttt\">antibiothérapie</span>.</div>\n\n      <h4 class=\"kw-def\">1 · <span class=\"kw-bio\">Test de diagnostic rapide</span> (TDR / TROD)</h4>\n      <ul>\n        <li><strong>Principe :</strong> détection des <span class=\"kw-bio\">antigènes de paroi</span> de <em>Streptococcus pyogenes</em> (polysaccharide C) sur <span class=\"kw-bio\">prélèvement oropharyngé</span>.</li>\n        <li><strong>Performance :</strong> <span class=\"kw-bio\">spécificité</span> ≈ <span class=\"kw-chiffre\">95 %</span> ; <span class=\"kw-bio\">sensibilité</span> <span class=\"kw-chiffre\">&gt; 90 %</span>. Résultat en <span class=\"kw-chiffre\">5 minutes</span>, gratuit, réalisable au cabinet.</li>\n      </ul>\n\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Terrain</span></th><th>Indication du <span class=\"kw-bio\">TDR</span></th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Enfant ≥ 3 ans</span></td><td><strong>Systématique</strong></td></tr>\n          <tr><td><span class=\"kw-etio\">Adulte (≥ 15 ans)</span></td><td>Si <span class=\"kw-def\">score de Mac Isaac</span> <span class=\"kw-chiffre\">≥ 2</span> (discutable si &lt; 2)</td></tr>\n          <tr><td><span class=\"kw-etio\">Enfant &lt; 3 ans</span></td><td><span class=\"kw-alerte\">Inutile</span> — angine quasi toujours <span class=\"kw-etio\">virale</span> à cet âge</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\"><span class=\"kw-def\">Score</span> de Mac Isaac (adulte)</h4>\n      <table >\n        <thead><tr><th>Critère</th><th>Points</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Fièvre &gt; 38 °C</span></td><td><span class=\"kw-chiffre\">+1</span></td></tr>\n          <tr><td><span class=\"kw-alerte\">Absence de toux</span></td><td><span class=\"kw-chiffre\">+1</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Adénopathies cervicales sensibles</span></td><td><span class=\"kw-chiffre\">+1</span></td></tr>\n          <tr><td>Atteinte amygdalienne (volume, exsudat)</td><td><span class=\"kw-chiffre\">+1</span></td></tr>\n          <tr><td>Âge <span class=\"kw-chiffre\">15 – 44 ans</span></td><td><span class=\"kw-chiffre\">0</span></td></tr>\n          <tr><td>Âge <span class=\"kw-chiffre\">≥ 45 ans</span></td><td><span class=\"kw-chiffre\">−1</span></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-danger\"><strong>Piège EDN.</strong> Le <span class=\"kw-def\">score</span> de Mac Isaac a une bonne VPN chez l'adulte mais <span class=\"kw-alerte\">n'est pas validé chez l'enfant</span> (où le <span class=\"kw-bio\">TDR</span> est systématique dès <span class=\"kw-chiffre\">3 ans</span>).</div>\n\n      <h4 class=\"kw-def\">2 · Interprétation du <span class=\"kw-bio\">TDR</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-bio\">TDR positif</span> :</strong> confirme l'étiologie SGA → <span class=\"kw-ttt\">antibiothérapie justifiée</span>.</li>\n        <li><strong><span class=\"kw-bio\">TDR négatif</span> sans FR de RAA :</strong> ni culture ni ATB → seuls <span class=\"kw-ttt\">antalgiques</span>/antipyrétiques.</li>\n        <li><strong><span class=\"kw-bio\">TDR négatif</span> avec FR de RAA :</strong> contrôle possible par <span class=\"kw-bio\">mise en culture</span> ; si positive → ATB.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">3 · Culture du prélèvement pharyngé</h4>\n      <ul>\n        <li>Peu réalisée (résultat en <span class=\"kw-chiffre\">1 à 2 jours</span>), réservée chez le <span class=\"kw-chiffre\">≥ 3 ans</span> à : recherche de résistance aux <span class=\"kw-ttt\">macrolides</span> ; <span class=\"kw-alerte\">échec thérapeutique à 72 h</span> ; <span class=\"kw-bio\">TDR</span> négatif + <strong>FR de RAA</strong>.</li>\n        <li><strong>FR de RAA :</strong> ATCD personnels de RAA ; épisodes multiples d'angine à SGA (<span class=\"kw-chiffre\">5 – 25 ans</span>) ; séjours en zone d'endémie (<span class=\"kw-etio\">Afrique</span>, <span class=\"kw-etio\">DOM-TOM</span>).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">4 · Examens non systématiques (selon le tableau)</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-bio\">Dépistage VIH</span></td><td>Suspicion de <span class=\"kw-alerte\">primo-infection VIH</span> (angine érythémateuse/érythématopultacée)</td></tr>\n          <tr><td><span class=\"kw-bio\">NFS-plaquettes</span></td><td>Angine pseudomembraneuse ou ulcéro-nécrotique (syndrome mononucléosique, neutropénie)</td></tr>\n          <tr><td><span class=\"kw-bio\">MNI-test</span> (± <span class=\"kw-bio\">sérologie</span> <span class=\"kw-etio\">EBV</span>)</td><td>Suspicion de MNI (érythématopultacée à <span class=\"kw-bio\">TDR</span> négatif, ou pseudomembraneuse)</td></tr>\n          <tr><td><span class=\"kw-bio\">Examen direct bactériologique</span></td><td>Suspicion d'angine de <span class=\"kw-etio\">Vincent</span>, <span class=\"kw-clinique\">chancre</span> <span class=\"kw-etio\">syphilitique</span>, <span class=\"kw-etio\">diphtérie</span></td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 217 — Syndrome mononucléosique</em></p>","frequence":7},{"id":"149-7","rang":"A","rubrique":"Prise en charge","titre":"Connaître les modalités de prescription du traitement de l'angine à streptocoque du groupe A","contenu":"<div class=\"obj-callout success\"><strong>1ʳᵉ intention.</strong> <span class=\"kw-ttt\">Amoxicilline</span> par voie orale, <span class=\"kw-chiffre\">2 ×/jour</span> pendant <span class=\"kw-chiffre\">6 jours</span>.</div>\n\n      <table >\n        <thead><tr><th>Situation</th><th>Molécule &amp; durée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td><span class=\"kw-ttt\">Amoxicilline</span> PO 2 ×/j × <span class=\"kw-chiffre\">6 jours</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\">Allergie aux pénicillines</span> (C<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span>G</span> / C3G orales)</td>\n            <td><strong>Enfant :</strong> <span class=\"kw-ttt\">cefpodoxime-proxétil</span> × <span class=\"kw-chiffre\">5 j</span><br>\n              <strong>Adulte :</strong> <span class=\"kw-ttt\">céfuroxime-axétil</span> × <span class=\"kw-chiffre\">4 j</span>, ou <span class=\"kw-ttt\">cefpodoxime-proxétil</span> / <span class=\"kw-ttt\">céfotiam</span> × <span class=\"kw-chiffre\">5 j</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ci\">CI à toutes les β-lactamines</span></td>\n            <td><span class=\"kw-ttt\">Macrolides</span> <strong>après culture + <span class=\"kw-bio\">antibiogramme</span></strong> (résistance SGA &lt; <span class=\"kw-chiffre\">10 %</span> en France) :<br>\n              <span class=\"kw-ttt\">Azithromycine</span> × <span class=\"kw-chiffre\">3 j</span> ; <span class=\"kw-ttt\">clarithromycine</span> ou <span class=\"kw-ttt\">josamycine</span> × <span class=\"kw-chiffre\">5 j</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\">Objectifs de l'<span class=\"kw-ttt\">antibiothérapie</span></h4>\n      <ul>\n        <li><strong>Si précoce :</strong> accélère la guérison de <span class=\"kw-chiffre\">≈ 24 h</span> ; réduit la contagiosité (patient non contagieux <span class=\"kw-chiffre\">24 h</span> après le début) ; diminue le risque de suppuration locorégionale.</li>\n        <li><strong>Même non précoce :</strong> prévient le <span class=\"kw-alerte\">RAA</span> (effet protecteur conservé jusqu'à <span class=\"kw-chiffre\">J9</span> du début des symptômes).</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>Tombé en annale.</strong> Il n'est <span class=\"kw-alerte\">pas démontré</span> que l'ATB prévient la <span class=\"kw-alerte\">glomérulonéphrite aiguë (GNA)</span> post-streptococcique (point de départ rarement pharyngé, plus souvent cutané). Et un <span class=\"kw-clinique\">phlegmon</span> péri-amygdalien reste possible <strong>même sous ATB bien conduit</strong>.</div>","frequence":4},{"id":"149-8","rang":"A","rubrique":"Prise en charge","titre":"Connaître la stratégie et les modalités de traitement des angines érythémateuses et érythémato-pultacées","contenu":"<div class=\"obj-callout success\"><strong>Stratégie globale = <span class=\"kw-bio\">TDR</span>-dépendante.</strong> On ne prescrit pas d'antibiotique sur la seule clinique : le <span class=\"kw-bio\">TDR</span> décide.</div>\n\n      <ul>\n        <li><strong><span class=\"kw-bio\">TDR positif</span> →</strong> <span class=\"kw-ttt\">antibiothérapie</span> anti-SGA (<span class=\"kw-ttt\">amoxicilline</span> 6 j) + traitement symptomatique.</li>\n        <li><strong><span class=\"kw-bio\">TDR négatif</span> →</strong> origine <span class=\"kw-etio\">virale</span> probable : <strong>pas d'antibiotique</strong>, traitement symptomatique seul (sauf FR de RAA → culture).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Quand l'antibiotique n'est PAS indiqué</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Virus</span> (la grande majorité).</li>\n        <li><span class=\"kw-etio\">Bactéries commensales</span> : <em><span class=\"kw-etio\">Haemophilus</span> influenzae / parainfluenzae</em>, <em>Moraxella catarrhalis</em>, <span class=\"kw-etio\">pneumocoque</span>, staphylocoque, <span class=\"kw-etio\">anaérobies</span>.</li>\n        <li><span class=\"kw-etio\">Streptocoques</span> des groupes <span class=\"kw-etio\">C, G, F</span> et <em>Arcanobacterium haemolyticum</em> (complications exceptionnelles).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Quand l'antibiotique EST nécessaire</h4>\n      <ul>\n        <li>Angine à <span class=\"kw-etio\">SGA</span> (<span class=\"kw-bio\">TDR</span>+).</li>\n        <li>Angines <span class=\"kw-etio\">diphtérique</span>, <span class=\"kw-etio\">gonococcique</span>, <span class=\"kw-etio\">syphilitique</span> (<span class=\"kw-clinique\">chancre</span>).</li>\n        <li>Angines nécrotiques : angine de <span class=\"kw-etio\">Vincent</span>, angine de <span class=\"kw-etio\">Ludwig</span> ; certaines bactéries <span class=\"kw-etio\">anaérobies</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Indications d'<span class=\"kw-alerte\">hospitalisation</span></h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Diphtérie</span> ; angine de <span class=\"kw-alerte\">Vincent</span>.</li>\n        <li><span class=\"kw-alerte\">Angine aphagiante</span> ; <span class=\"kw-alerte\">gingivo-stomatite herpétique sévère</span> empêchant l'alimentation.</li>\n        <li>Certaines complications de l'angine streptococcique ou de la MNI.</li>\n      </ul>","frequence":2},{"id":"149-9","rang":"A","rubrique":"Prise en charge","titre":"Connaître les mesures symptomatiques","contenu":"<div class=\"obj-callout success\"><strong>Mesures symptomatiques (tous <span class=\"kw-clinique\">les</span> cas).</strong> <span class=\"kw-ttt\">Antalgiques / antipyrétiques</span> : <span class=\"kw-ttt\">paracétamol</span> en <strong>1ʳᵉ intention</strong>.</div>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-ci\">Contre-indication</span> clé.</strong> <span class=\"kw-ci\">Pas de corticoïdes</span> ni d'<span class=\"kw-ci\">AINS</span> : ils <span class=\"kw-alerte\">augmentent le risque de complications locorégionales suppurées</span>.</div>\n\n      <ul>\n        <li><strong>Exceptions (<span class=\"kw-ttt\">corticoïdes</span> autorisés) :</strong> certaines complications de la <span class=\"kw-etio\">diphtérie</span> et <span class=\"kw-clinique\">les</span> formes sévères de <span class=\"kw-etio\">MNI</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Mesures préventives spécifiques</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Mesure</th></tr></thead>\n        <tbody>\n          <tr><td>Angine à <span class=\"kw-etio\">SGA</span> / scarlatine</td><td><span class=\"kw-clinique\">Éviction scolaire</span> pendant <span class=\"kw-chiffre\">2 jours après le début de l'ATB</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Diphtérie</span></td><td><span class=\"kw-def\">Isolement</span> gouttelettes ; <span class=\"kw-alerte\">déclaration obligatoire (ARS)</span> ; éviction ; <span class=\"kw-def\">dépistage</span> + <span class=\"kw-ttt\">antibioprophylaxie</span> des contacts</td></tr>\n          <tr><td><span class=\"kw-etio\">Syphilis</span> / <span class=\"kw-etio\">gonocoque</span></td><td><span class=\"kw-def\">Dépistage</span> des autres <span class=\"kw-clinique\">IST</span> (dont <span class=\"kw-etio\">VIH</span>) chez le cas index et <span class=\"kw-clinique\">les</span> contacts</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"149-10","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les complications générales des angines","contenu":"<div class=\"callout callout-info\"><strong>Cadre.</strong> Ces complications concernent l'angine à <span class=\"kw-etio\">SBHA</span>. Elles surviennent dans <span class=\"kw-chiffre\">≈ 1 %</span> des angines à SGA et sont soit <strong>toxiniques</strong>, soit <strong>immunologiques (post-streptococciques)</strong>.</div>\n\n      <h4 class=\"kw-def\">Complications toxiniques</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Scarlatine</span>.</li>\n        <li><span class=\"kw-alerte\">Choc toxique streptococcique</span> ; <span class=\"kw-alerte\">fasciite</span> (risque accru chez un sujet contaminé en contexte de varicelle).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Complications immunologiques (post-streptococciques)</h4>\n      <p>Mécanisme : complexes immuns <span class=\"kw-bio\">antigènes SGA + IgG</span> se déposant dans <span class=\"kw-clinique\">les</span> glomérules et les articulations, activant le <span class=\"kw-bio\">complément</span>.</p>\n      <table >\n        <thead><tr><th>Complication</th><th>Délai</th><th>Tableau</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">GNA post-infectieuse</span> (GNAPI)</td>\n            <td><span class=\"kw-chiffre\">10 – 20 j</span></td>\n            <td><span class=\"kw-clinique\">Syndrome néphritique aigu</span> (<span class=\"kw-etio\">HTA</span>, <span class=\"kw-clinique\">œdèmes</span>, <span class=\"kw-bio\">protéinurie</span>, <span class=\"kw-bio\">hématurie</span>, IRA) ; <span class=\"kw-bio\">hypocomplémentémie</span>. Guérison sans séquelle en <span class=\"kw-chiffre\">2 mois</span> (<span class=\"kw-chiffre\">90 %</span> enfants,<span class=\"kw-chiffre\"> 80 %</span> adultes).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">RAA</span> (rhumatisme articulaire aigu)</td>\n            <td><span class=\"kw-chiffre\">15 – 20 j</span></td>\n            <td>Début brutal par <span class=\"kw-clinique\">polyarthrite</span> mobile migratrice des grosses articulations, ou insidieux par <span class=\"kw-alerte\">atteinte cardiaque inaugurale</span>. Autres : <span class=\"kw-clinique\">érythème</span> noueux, nodosités de Meynet, chorée de Sydenham.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong><span class=\"kw-def\">Pronostic</span> du RAA.</strong> L'<span class=\"kw-alerte\">atteinte cardiaque (cardite)</span> est l'élément pronostique essentiel : d'autant plus fréquente que le sujet est jeune. Risque immédiat = <span class=\"kw-alerte\">insuffisance cardiaque</span> ; risque tardif = <span class=\"kw-alerte\">séquelles valvulaires</span> (IM &gt; IA).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 261 — Néphropathie glomérulaire</em></p>","frequence":3},{"id":"149-11","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir identifier les complications suppuratives loco-régionales des angines","contenu":"<div class=\"callout callout-danger\"><strong><span class=\"kw-alerte\">Urgence</span>.</strong> Toute angine qui se complique localement impose : reconnaissance des signes d'alerte, <span class=\"kw-imagerie\">imagerie (TDM le plus souvent)</span>, et transfert vers un centre spécialisé pour traitement médico-chirurgical.</div>\n\n      <h4 class=\"kw-def\">Signes d'alerte 🚩</h4>\n      <ul>\n        <li><span class=\"kw-alerte\">Unilatéralisation</span> des symptômes.</li>\n        <li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-alerte\">syndrome septique sévère</span>.</li>\n        <li><span class=\"kw-clinique\">Odynophagie sévère</span>, <span class=\"kw-alerte\">dyspnée</span>.</li>\n        <li><span class=\"kw-clinique\">Trismus</span>, <span class=\"kw-clinique\">torticolis</span>, <span class=\"kw-clinique\">tuméfaction latéro-cervicale</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Orientation par le couple <span class=\"kw-clinique\">trismus</span> / torticolis</h4>\n      <table >\n        <thead><tr><th>Signes</th><th>Complication évoquée</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-clinique\">Trismus</span> sans torticolis</td><td><span class=\"kw-def\">Phlegmon péri-amygdalien</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Trismus</span> + <span class=\"kw-clinique\">torticolis</span></td><td><span class=\"kw-def\">Infection pré-stylienne</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Torticolis</span> sans <span class=\"kw-clinique\">trismus</span></td><td><span class=\"kw-def\">Adénophlegmon</span> ; infections rétropharyngées / rétrostyliennes</td></tr>\n        </tbody>\n      </table>\n\n      <h4 class=\"kw-def\"><span class=\"kw-clinique\">Phlegmon</span> péri-amygdalien +++</h4>\n      <ul>\n        <li><strong>Définition :</strong> <span class=\"kw-clinique\">cellulite</span> suppurée entre la <span class=\"kw-def\">capsule amygdalienne</span> et la paroi pharyngée ; secondaire à une angine traînante, ou inaugural dans <span class=\"kw-chiffre\">10 %</span> des cas.</li>\n        <li><strong>Clinique :</strong> <span class=\"kw-clinique\">fièvre</span> élevée, douleur pharyngée unilatérale, <span class=\"kw-clinique\">trismus</span>, haleine fétide, <span class=\"kw-clinique\">voix de « patate chaude »</span>, hypersalivation.</li>\n        <li><strong>Examen :</strong> bombement du pilier antérieur « en verre de montre » masquant l'amygdale ; <span class=\"kw-clinique\">luette œdématiée refoulée du côté opposé</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Phlegmon</span> antérieur</strong> : bombement du <span class=\"kw-clinique\">pôle supérieur du pilier antérieur</span>, habituellement <strong>avec</strong> <span class=\"kw-clinique\">trismus</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Phlegmon</span> postérieur</strong> (plus rare) : <span class=\"kw-clinique\">pilier postérieur transformé en bourrelet vertical blanchâtre œdématié</span>, habituellement <strong>sans</strong> <span class=\"kw-clinique\">trismus</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Infections péripharyngées (<span class=\"kw-def\">terrain</span> pédiatrique &lt;<span class=\"kw-chiffre\"> 7 ans</span> pour <span class=\"kw-clinique\">les</span> adénites)</h4>\n      <table >\n        <thead><tr><th>Entité</th><th>Repères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Adénite rétropharyngée</span></td><td>Enfant &lt;<span class=\"kw-chiffre\"> 7 ans</span> ; <span class=\"kw-clinique\">tuméfaction</span> <strong>médiane</strong> de la paroi pharyngée ; risque d'<span class=\"kw-alerte\">obstruction des voies aériennes</span></td></tr>\n          <tr><td><span class=\"kw-def\">Adénite rétrostylienne</span></td><td>Enfant &lt;<span class=\"kw-chiffre\"> 7 ans</span> ; <span class=\"kw-clinique\">tuméfaction</span> <strong>latérale rétro-amygdalienne</strong> ; risque de <span class=\"kw-alerte\">complications neuro-vasculaires</span></td></tr>\n          <tr><td><span class=\"kw-def\">Infection pré-stylienne</span></td><td>Adulte / adolescent ; <span class=\"kw-clinique\">porte d'entrée</span> dentaire +++ ; risque de <span class=\"kw-alerte\">cellulite cervicale profonde extensive</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong><span class=\"kw-clinique\">Cellulite</span> cervicale profonde extensive.</strong> Infection nécrosante des espaces celluleux pouvant diffuser parotide → sous-mandibulaire → rétrostylien → rétropharyngé → <span class=\"kw-alerte\">médiastin (médiastinite)</span>. <span class=\"kw-alerte\"><span class=\"kw-def\">Pronostic</span> vital</span> engagé.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 158 — <span class=\"kw-clinique\">Sepsis</span> et <span class=\"kw-alerte\">choc septique</span></em></p>","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/peritonsillar-abscess","label":"Radiopaedia : Peritonsillar abscess (phlegmon)"},{"href":"https://radiopaedia.org/articles/retropharyngeal-abscess","label":"Radiopaedia : Retropharyngeal abscess"}]},{"id":"149-12","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des angines pseudomembraneuses","contenu":"<div class=\"obj-callout success\"><strong>Sémiologie commune.</strong> L'amygdale est recouverte de <span class=\"kw-clinique\">fausses membranes nacrées</span>, extensives, <strong>pouvant déborder</strong> sur la région amygdalienne, le voile et ses piliers (≠ enduit pultacé qui ne déborde pas).</div>\n\n      <p>Deux étiologies principales à distinguer impérativement :</p>\n      <table >\n        <thead><tr><th>Critère</th><th>MNI (<span class=\"kw-etio\">EBV</span>)</th><th>Diphtérie (à distinguer)</th></tr></thead>\n        <tbody>\n          <tr><td>Germe</td><td><span class=\"kw-etio\">EBV</span></td><td><span class=\"kw-etio\">Corynebacterium diphtheriae</span> (BG+)</td></tr>\n          <tr><td>Fréquence</td><td>Plus fréquente</td><td><span class=\"kw-alerte\">Exceptionnelle</span></td></tr>\n          <tr><td><span class=\"kw-def\">Terrain</span></td><td>Adolescent, adulte jeune</td><td>Absence de <span class=\"kw-ttt\">vaccination</span> + retour de zone d'endémie</td></tr>\n          <tr><td>Fausses membranes</td><td><span class=\"kw-clinique\">Non adhérentes</span> ; en regard des amygdales ; <strong>respectant la luette</strong></td><td><span class=\"kw-alerte\">Adhérentes</span>, non dissociables ; <span class=\"kw-alerte\">rapidement extensives</span>, débordant sur luette + pharynx postérieur</td></tr>\n          <tr><td>État général</td><td><span class=\"kw-clinique\">Fièvre élevée et durable</span> (<span class=\"kw-chiffre\">10-15 j</span>), <span class=\"kw-clinique\">asthénie</span></td><td><span class=\"kw-clinique\">Fièvre modérée</span>, <span class=\"kw-alerte\">signes d'imprégnation toxinique</span> (<span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">tachycardie</span>)</td></tr>\n          <tr><td><span class=\"kw-clinique\">Adénopathies</span></td><td><span class=\"kw-clinique\">Cervicales bilatérales postérieures</span>, <span class=\"kw-clinique\">splénomégalie</span></td><td><span class=\"kw-clinique\">Sous-angulo-mandibulaires</span> ; <span class=\"kw-clinique\">coryza unilatéral</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Réflexe sérologique.</strong> Devant une angine pseudomembraneuse : <span class=\"kw-bio\">NFS-plaquettes</span> + <span class=\"kw-bio\">MNI-test</span> (<span class=\"kw-bio\">syndrome mononucléosique</span>, <span class=\"kw-bio\">cytolyse hépatique</span>, <span class=\"kw-bio\">thrombopénie</span> pour la MNI).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 217 — Syndrome mononucléosique · 168 — Herpesvirus</em></p>","frequence":0},{"id":"149-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge d'une angine pseudo-membraneuse à EBV","contenu":"<div class=\"obj-callout success\"><strong>MNI = traitement symptomatique.</strong> Pas d'antibiotique (origine <span class=\"kw-etio\">virale</span>, <span class=\"kw-etio\">EBV</span>) : <span class=\"kw-ttt\">antalgiques / antipyrétiques</span> et <span class=\"kw-clinique\">repos</span>.</div>\n\n      <ul>\n        <li><strong><span class=\"kw-ci\">Éviter les aminopénicillines</span> (<span class=\"kw-ttt\">amoxicilline</span>, <span class=\"kw-ttt\">ampicilline</span>) :</strong> elles déclenchent un <span class=\"kw-alerte\">exanthème morbiliforme</span> (<span class=\"kw-clinique\">rash</span> après pénicilline A) — piège classique du sujet <span class=\"kw-clinique\">fébrile</span> « traité comme une angine <span class=\"kw-etio\">bactérienne</span> ».</li>\n        <li><strong><span class=\"kw-ttt\">Corticoïdes</span> :</strong> réservés aux <span class=\"kw-alerte\">formes sévères</span> de <span class=\"kw-def\">MNI</span> (<span class=\"kw-clinique\">obstruction</span>, complications).</li>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong> si complication de la <span class=\"kw-def\">mononucléose infectieuse</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><span class=\"kw-clinique\">Évolution</span> généralement favorable ; <span class=\"kw-clinique\">asthénie</span> parfois prolongée. La <span class=\"kw-clinique\">splénomégalie</span> justifie la prudence (éviter <span class=\"kw-clinique\">les</span> sports de <span class=\"kw-def\">contact</span> — risque de <span class=\"kw-alerte\">rupture splénique</span>).</div>","frequence":0},{"id":"149-14","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques d'une angine pseudo-membraneuse diphtérique","contenu":"<div class=\"callout callout-danger\"><strong>À évoquer systématiquement malgré sa rareté.</strong> La diphtérie est <span class=\"kw-alerte\">exceptionnelle</span> en France (<span class=\"kw-ttt\">vaccination</span> obl<span class=\"kw-chiffre\">iga</span>toire) mais grave ; c'est une <span class=\"kw-alerte\">maladie à déclaration obligatoire</span>.</div>\n\n      <h4 class=\"kw-def\">Deux points qui orientent (<span class=\"kw-def\">terrain</span>)</h4>\n      <ul>\n        <li><span class=\"kw-etio\">Absence de vaccination</span>.</li>\n        <li><span class=\"kw-etio\">Retour d'une zone d'endémie</span> (Europe de l'Est, pays en développement).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Clinique</h4>\n      <ul>\n        <li><strong>État général :</strong> <span class=\"kw-clinique\">asthénie inhabituelle</span>, <span class=\"kw-clinique\">malaise</span>, <span class=\"kw-clinique\">fièvre</span> modérée, <span class=\"kw-alerte\">signes d'imprégnation toxinique</span> (pâleur, <span class=\"kw-clinique\">tachycardie</span>).</li>\n        <li><strong>Angine :</strong> fausses membranes <span class=\"kw-alerte\">adhérentes</span>, non dissociables, <span class=\"kw-alerte\">rapidement extensives</span>, débordant <span class=\"kw-clinique\">les</span> amygdales et <strong>envahissant la luette et le pharynx postérieur</strong>.</li>\n        <li><strong>Signes associés :</strong> coryza (<span class=\"kw-clinique\">jetage nasal unilatéral</span>) ; <span class=\"kw-clinique\">adénopathies</span> sous-angulo-mandibulaires.</li>\n        <li><strong>Biologie :</strong> <span class=\"kw-bio\">hyperleucocytose à PNN</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Germe :</strong> complexe <span class=\"kw-etio\">Corynebacterium diphtheriae</span> (ou <em>C. ulcerans</em> / <em>C. pseudotuberculosis</em>) — bacille Gram +, dangereux si la souche porte le <span class=\"kw-def\">gène de la toxine diphtérique</span>. Incubation <span class=\"kw-chiffre\">&lt; 7 jours</span>.</div>","frequence":0},{"id":"149-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des angines vésiculeuses","contenu":"<div class=\"obj-callout success\"><strong>Sémiologie.</strong> Muqueuse pharyngée <span class=\"kw-etio\">inflammatoire</span> portant des <span class=\"kw-clinique\">vésicules</span> non limitées aux amygdales (<span class=\"kw-clinique\">voile</span>, <span class=\"kw-clinique\">piliers</span>, <span class=\"kw-clinique\">parois pharyngée et jugale</span>), puis des <span class=\"kw-clinique\">érosions à enduit jaunâtre</span> entourées d'un <span class=\"kw-clinique\">halo inflammatoire</span> après <span class=\"kw-alerte\">rupture</span>. Tableau <span class=\"kw-alerte\">très douloureux</span>, touchant surtout l'<span class=\"kw-etio\">enfant</span>.</div>\n\n      <table >\n        <thead><tr><th>Forme</th><th>Caractéristiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Angine herpétique</span> (<span class=\"kw-etio\">HSV-1</span>)</td>\n            <td><strong>Début brutal :</strong> <span class=\"kw-clinique\">fièvre</span> <span class=\"kw-chiffre\">39 – 40 °C</span> + <span class=\"kw-clinique\">frissons</span> + <span class=\"kw-clinique\">odynophagie intense</span><br>\n              <strong>Examen :</strong> <span class=\"kw-clinique\">amygdales rouge vif</span> avec <span class=\"kw-clinique\">bouquets de petites vésicules hyalines</span> ; <span class=\"kw-clinique\">adénopathies sous-angulo-maxillaires</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Herpangine</span></td>\n            <td><strong>Enfant <span class=\"kw-chiffre\">1 – 7 ans</span></strong>, épidémies <span class=\"kw-etio\">estivales</span> (<span class=\"kw-etio\">entérovirus</span>)<br>\n              <span class=\"kw-clinique\">Vésicules</span> <strong>restant localisées à l'oropharynx</strong> ; <span class=\"kw-clinique\">syndrome pieds-mains-bouche</span> possible</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p>","frequence":0},{"id":"149-16","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies des angines vésiculeuses","contenu":"<div class=\"callout callout-warn\"><strong>Règle absolue.</strong> <span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">angines vésiculeuses</span> sont <strong>toujours <span class=\"kw-etio\">virales</span></strong> (deux étiologies, aucune <span class=\"kw-etio\">bactérienne</span>).</div>\n\n      <ul>\n        <li><strong><span class=\"kw-def\">Angine herpétique</span> :</strong> <span class=\"kw-etio\">HSV-1</span> (<span class=\"kw-etio\">herpès simplex virus de type 1</span>).</li>\n        <li><strong><span class=\"kw-def\">Herpangine</span> :</strong> <span class=\"kw-etio\">entérovirus</span> — <span class=\"kw-etio\">échovirus</span>, <span class=\"kw-etio\">coxsackie du groupe A</span>. Contexte <span class=\"kw-etio\">estival</span>, <span class=\"kw-etio\">enfant</span>, syndrome <span class=\"kw-clinique\">pieds-mains-bouche</span>, <span class=\"kw-clinique\">lésions localisées à l'oropharynx</span>.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 168 — Herpesvirus</em></p>","frequence":0},{"id":"149-17","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître l'évolution des angines vésiculeuses","contenu":"<div class=\"obj-callout success\"><strong><span class=\"kw-clinique\">Évolution</span> bénigne.</strong> <span class=\"kw-clinique\">Guérison spontanée</span>, sans complication ni séquelle.</div>\n\n      <ul>\n        <li><strong><span class=\"kw-def\">Angine herpétique</span> (<span class=\"kw-etio\">HSV-1</span>) :</strong> <span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">bénigne</span> en <span class=\"kw-chiffre\">4 à 5 jours</span>, sans <span class=\"kw-clinique\">complication</span> ni <span class=\"kw-clinique\">séquelle</span>.</li>\n        <li><strong><span class=\"kw-def\">Herpangine</span> :</strong> <span class=\"kw-clinique\">évolution</span> <span class=\"kw-clinique\">bénigne</span> ; <span class=\"kw-clinique\">régression spontanée</span> en quelques jours.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\"><strong>Seule réserve.</strong> La <span class=\"kw-alerte\">gingivo-stomatite herpétique sévère</span> peut <span class=\"kw-clinique\">empêcher l'alimentation</span> (<span class=\"kw-clinique\">déshydratation</span>) et justifier une <span class=\"kw-clinique\">hospitalisation</span> (cf. prise en charge).</div>","frequence":0},{"id":"149-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge d'une angine vésiculeuse","contenu":"<div class=\"obj-callout success\"><strong>Prise en charge ambulatoire symptomatique.</strong> Pas d'antibiotique (origine <span class=\"kw-etio\">virale</span>).</div>\n\n      <ul>\n        <li><span class=\"kw-ttt\">Antalgiques</span> / <span class=\"kw-ttt\">antipyrétiques</span> ; <span class=\"kw-clinique\">hydratation</span>.</li>\n        <li><strong>± <span class=\"kw-ttt\">Antiviral per os</span></strong> (<span class=\"kw-ttt\">aciclovir</span>) si <span class=\"kw-clinique\">primo-infection herpétique</span> (<span class=\"kw-etio\">HSV-1</span>).</li>\n        <li><strong><span class=\"kw-clinique\">Hospitalisation</span></strong> si <span class=\"kw-alerte\">gingivo-stomatite herpétique sévère</span> <span class=\"kw-clinique\">empêchant l'alimentation</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\"><strong><span class=\"kw-def\">Herpangine</span> :</strong> traitement <span class=\"kw-ttt\">symptomatique</span> seul (<span class=\"kw-ttt\">antalgiques</span>), <span class=\"kw-clinique\">évolution</span> spontanément <span class=\"kw-clinique\">bénigne</span>.</div>","frequence":0},{"id":"149-19","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques des angines ulcéreuses et ulcéro-nécrotiques","contenu":"<div class=\"obj-callout success\"><strong>Sémiologie commune.</strong> Amygdale <span class=\"kw-clinique\">ulcérée</span>, en règle <strong>unilatérale</strong> (sauf agranulocytose, bilatérale), <span class=\"kw-clinique\">profonde</span>, recouverte d'un <span class=\"kw-clinique\">enduit nécrotique</span>, avec extension possible au voile et au pharynx postérieur.</div>\n\n      <h4 class=\"kw-def\">Angine de Vincent (chef de file)</h4>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span> :</strong> <span class=\"kw-etio\">adolescent / adulte jeune</span> ; FR = <span class=\"kw-etio\">tabac</span>, mauvais état buccodentaire ; début insidieux.</li>\n        <li><strong>Symptômes :</strong> état <span class=\"kw-clinique\">subfébrile</span>, <span class=\"kw-clinique\">dysphagie unilatérale légère</span>, <span class=\"kw-clinique\">fétidité de l'haleine</span> (germes <span class=\"kw-etio\">anaérobies</span>).</li>\n        <li><strong>Examen :</strong> <span class=\"kw-clinique\">ulcération</span> unilatérale <span class=\"kw-clinique\">atone</span>, à <span class=\"kw-clinique\">bords irréguliers</span> surélevés, <span class=\"kw-alerte\">non indurée au toucher</span> (≠ <span class=\"kw-clinique\">chancre</span>), recouverte d'un enduit pultacé gris friable.</li>\n        <li><strong>Paraclinique :</strong> <span class=\"kw-bio\">NFS normale</span> ; prélèvement = <span class=\"kw-etio\">association fuso-spirillaire</span> (<em><span class=\"kw-etio\">Fusobacterium</span></em> + spirochète).</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>À distinguer (induration = piège).</strong> Le <span class=\"kw-alerte\">chancre syphilitique</span> donne une <span class=\"kw-clinique\">ulcération</span> unilatérale <span class=\"kw-alerte\">indurée et indolore</span> ; un <span class=\"kw-alerte\">cancer de l'amygdale</span> est unilatéral, induré, saigne au toucher (<span class=\"kw-etio\">alcool</span>/tabac, âge). Toute forme unilatérale traînante impose d'éliminer un cancer.</div>","frequence":0},{"id":"149-20","rang":"A","rubrique":"Étiologies","titre":"Connaître les étiologies des angines ulcéreuses et ulcéro-nécrotiques","contenu":"<table >\n        <thead><tr><th>Étiologie</th><th>Repères</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-etio\">Angine de Vincent</span></td><td><span class=\"kw-etio\">Association fuso-spirillaire</span> ; <span class=\"kw-clinique\">ulcération</span> <span class=\"kw-clinique\">non indurée</span> ; <span class=\"kw-clinique\">haleine fétide</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Chancre syphilitique</span></td><td><span class=\"kw-etio\">Treponema pallidum</span> ; <span class=\"kw-clinique\">ulcération</span> <span class=\"kw-clinique\">indurée, indolore</span> ; <span class=\"kw-etio\">rapports oro-génitaux</span></td></tr>\n          <tr><td><span class=\"kw-etio\">Agranulocytose / hémopathie</span></td><td>Ulcérations <span class=\"kw-clinique\">bilatérales diffuses</span> ; <span class=\"kw-clinique\">ne saignent pas</span> ; <span class=\"kw-etio\">leucose aiguë</span> (<span class=\"kw-clinique\">gingivite hypertrophique</span>)</td></tr>\n          <tr><td><span class=\"kw-etio\">Cancer de l'amygdale</span></td><td><span class=\"kw-clinique\">Unilatéral</span>, <span class=\"kw-alerte\">induré</span>, <span class=\"kw-alerte\">saigne au toucher</span> ; <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">alcool-tabac</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Réflexe.</strong> Devant une angine ulcéro-nécrotique : <span class=\"kw-bio\">NFS-plaquettes</span> (<span class=\"kw-etio\">agranulocytose</span>, <span class=\"kw-etio\">hémopathie</span>) et <span class=\"kw-bio\">examen direct bactériologique</span> (<span class=\"kw-etio\">Vincent</span>, <span class=\"kw-etio\">syphilis</span>). Toute <span class=\"kw-clinique\">ulcération unilatérale traînante</span> = <span class=\"kw-alerte\">biopsie pour éliminer un cancer</span>.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span></em></p>","frequence":0},{"id":"149-21","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître l'évolution des angines ulcéreuses et ulcéro-nécrotiques","contenu":"<ul>\n        <li><strong>Angine de <span class=\"kw-etio\">Vincent</span> :</strong> <span class=\"kw-clinique\">évolution</span> <strong><span class=\"kw-clinique\">bénigne</span> en <span class=\"kw-chiffre\">8 à 10 jours</span></strong> sous <span class=\"kw-ttt\">pénicilline</span>.</li>\n        <li><strong><span class=\"kw-clinique\">Chancre</span> <span class=\"kw-etio\">syphilitique</span> :</strong> <span class=\"kw-clinique\">guérison de la lésion</span> sous <span class=\"kw-ttt\">pénicilline</span>, mais l'<span class=\"kw-etio\">infection syphilitique</span> suit son cours (<span class=\"kw-bio\">sérologies</span>, traitement).</li>\n        <li><strong><span class=\"kw-etio\">Cancer</span> / <span class=\"kw-etio\">hémopathie</span> :</strong> <span class=\"kw-clinique\">pronostic propre</span> à la pathologie causale ; <span class=\"kw-clinique\">orientation spécialisée</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-danger\"><strong>Complication redoutée de l'angine de Vincent.</strong> Risque de complications locales suppurées : <span class=\"kw-alerte\">phlegmon péri-amygdalien</span> et <span class=\"kw-alerte\">syndrome de Lemierre</span> 🔥 (voir objectif dédié).</div>","frequence":0},{"id":"149-22","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les signes cliniques et la prise en charge d'un syndrome de Lemierre","contenu":"<div class=\"callout callout-danger\"><strong>Rare mais grave.</strong> Le <span class=\"kw-def\">syndrome de Lemierre</span> associe pharyngite + atteinte amygdalienne, <span class=\"kw-alerte\">thrombose septique de la veine jugulaire interne</span>, et <span class=\"kw-alerte\">infarctus / abcès pulmonaires</span> par emboles septiques. Germe = <span class=\"kw-etio\">Fusobacterium necrophorum</span>. <span class=\"kw-def\">Mortalité</span> <span class=\"kw-chiffre\">≈ 5 %</span>.</div>\n\n      <h4 class=\"kw-def\">Clinique</h4>\n      <ul>\n        <li><span class=\"kw-def\">Terrain</span> : <span class=\"kw-etio\">adolescent / adulte jeune</span> en bonne santé, <span class=\"kw-chiffre\">4 – 5 jours</span> après une pharyngite.</li>\n        <li>État fébrile avec <span class=\"kw-clinique\">frissons répétés</span>, <span class=\"kw-clinique\">AEG</span> ; <span class=\"kw-clinique\">douleur latéro-cervicale</span>.</li>\n        <li>Signes pulmonaires : <span class=\"kw-clinique\">douleur thoracique</span>, <span class=\"kw-clinique\">dyspnée</span>, douleurs pleurétiques, <span class=\"kw-clinique\">hémoptysie</span>.</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Paraclinique</h4>\n      <ul>\n        <li>Biologie aspécifique (<span class=\"kw-bio\">CRP élevée</span>).</li>\n        <li><span class=\"kw-imagerie\">TDM cervico-thoracique injectée</span> = imagerie de choix (thrombose VJI + emboles).</li>\n      </ul>\n\n      <h4 class=\"kw-def\">Prise en charge</h4>\n      <ul>\n        <li><span class=\"kw-ttt\">Antibiothérapie IV</span> couvrant <em>F. necrophorum</em> et <span class=\"kw-etio\">streptocoques</span> oraux : <span class=\"kw-ttt\">amoxicilline-acide clavulanique</span>, ou <span class=\"kw-ttt\">carbapénème</span>, ou <span class=\"kw-ttt\">métronidazole</span> — IV <span class=\"kw-clinique\">les</span> 2 premières semaines, durée totale <span class=\"kw-chiffre\">6 semaines</span>.</li>\n        <li><span class=\"kw-clinique\">Drainage</span> des collections, débridement des tissus nécrotiques.</li>\n        <li><span class=\"kw-ttt\">Anticoagulation</span> : controversée, discutée au cas par cas.</li>\n      </ul>","frequence":0},{"id":"149-23","rang":"B","rubrique":"Prise en charge","titre":"Connaître la prise en charge d'une angine ulcéreuses et ulcéro-nécrotiques","contenu":"<p>La prise en charge dépend de l'étiologie, <strong>après avoir éliminé une <span class=\"kw-clinique\">syphilis</span></strong> :</p>\n\n      <table >\n        <thead><tr><th>Étiologie</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\">Angine de Vincent</span></td>\n            <td><span class=\"kw-ttt\">Amoxicilline</span> (si <span class=\"kw-ci\">allergie</span> : <span class=\"kw-ttt\">métronidazole</span>) — très efficace<br>\n              + consultation dentaire avec <span class=\"kw-imagerie\">panoramique dentaire</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Chancre syphilitique</span></td>\n            <td><span class=\"kw-ttt\">Pénicilline G retard</span> (benzathine-benzylpénicilline) <span class=\"kw-chiffre\">2,4 MUI IM</span> en <strong>1 injection</strong><br>\n              + <span class=\"kw-bio\">sérologie VIH</span> systématique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\">Cancer / hémopathie</span></td>\n            <td>Pas d'<span class=\"kw-ttt\">antibiothérapie</span> « d'angine » : <strong>orientation spécialisée</strong> (<span class=\"kw-clinique\">biopsie</span>, <span class=\"kw-bio\">NFS</span>-<span class=\"kw-bio\">myélogramme</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Avant tout traitement de <span class=\"kw-etio\">Vincent</span> :</strong> éliminer un <span class=\"kw-alerte\">chancre syphilitique</span> (<span class=\"kw-bio\">sérologies</span>) et un <span class=\"kw-alerte\">cancer</span> (<span class=\"kw-clinique\">forme unilatérale traînante</span>).</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 162 — <span class=\"kw-clinique\">IST</span> · 169 — <span class=\"kw-etio\">VIH</span></em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Bénin :</strong> la majorité des <span class=\"kw-etio\">angines érythémateuses/pultacées</span> évoluent favorablement en <span class=\"kw-chiffre\">3-4 jours</span>, prise en charge <span class=\"kw-ttt\">ambulatoire</span>.<br><strong><span class=\"kw-alerte\">Urgence</span> :</strong> reconnaître <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">complications suppuratives loco-régionales</span> (<span class=\"kw-clinique\">phlegmon</span>, infections péripharyngées, cellulite cervicale) → <span class=\"kw-imagerie\">TDM cervicale</span> + transfert en centre spécialisé pour traitement <span class=\"kw-ttt\">médico-chirurgical</span>.<br><strong>1er geste :</strong> identifier les <span class=\"kw-alerte\">signes d'alerte</span> et organiser le transfert ; ne pas retarder par des examens inutiles.<br><strong>À évoquer :</strong> <span class=\"kw-etio\">diphtérie</span> (exceptionnelle mais grave, <span class=\"kw-ttt\">déclaration obligatoire</span>) et <span class=\"kw-alerte\">syndrome de Lemierre</span> (thrombose septique de la <span class=\"kw-clinique\">veine jugulaire interne</span>, <span class=\"kw-def\">mortalité</span> <span class=\"kw-chiffre\">~5 %</span>).</p>","hospit":"<p><strong>Ambulatoire :</strong> angine non compliquée (érythémateuse/pultacée, vésiculeuse, <span class=\"kw-etio\">angine de Vincent</span> simple après élimination d'une <span class=\"kw-clinique\">syphilis</span>).<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-etio\">diphtérie</span>, <span class=\"kw-etio\">angine de Vincent</span>, <span class=\"kw-alerte\">angine aphagiante</span>, certaines complications de l'<span class=\"kw-etio\">angine streptococcique</span> ou de la <span class=\"kw-etio\">mononucléose infectieuse</span>, <span class=\"kw-alerte\">gingivo-stomatite herpétique sévère empêchant l'alimentation</span>.<br><strong>Centre spécialisé ORL :</strong> <span class=\"kw-alerte\">infections péripharyngées</span> et <span class=\"kw-alerte\">cellulite cervicale profonde</span> → transfert pour traitement <span class=\"kw-ttt\">médico-chirurgical</span>.</p>","redflags":"<ul><li><span class=\"kw-alerte\">Unilatérisation des symptômes</span> (douleur ou <span class=\"kw-clinique\">tuméfaction</span> d'un seul côté)</li><li><span class=\"kw-alerte\">AEG</span>, <span class=\"kw-alerte\">syndrome septique sévère</span></li><li><span class=\"kw-clinique\">Odynophagie sévère</span>, <span class=\"kw-alerte\">dyspnée</span></li><li><span class=\"kw-clinique\">Inflammation cutanée</span>, <span class=\"kw-clinique\">trismus</span>, <span class=\"kw-clinique\">torticolis</span>, <span class=\"kw-clinique\">tuméfaction latérocervicale</span></li><li><span class=\"kw-clinique\">Trismus</span> sans torticolis → <span class=\"kw-etio\">phlegmon péri-amygdalien</span></li><li><span class=\"kw-clinique\">Trismus + torticolis</span> → <span class=\"kw-etio\">infection pré-stylienne</span></li><li><span class=\"kw-clinique\">Torticolis</span> sans <span class=\"kw-clinique\">trismus</span> → <span class=\"kw-etio\">adénophlegmon</span>, <span class=\"kw-etio\">infection rétropharyngée/rétrostylienne</span></li><li><span class=\"kw-alerte\">Angine aphagiante</span> empêchant l'alimentation</li></ul>","principes":"<p>Le diagnostic d'angine est <span class=\"kw-clinique\">clinique</span> ; aucun signe n'affirme le <span class=\"kw-etio\">SGA</span> → seul le <span class=\"kw-bio\">TDR</span> tranche et conditionne l'<span class=\"kw-ttt\">antibiothérapie</span>.</p><p><strong>Indication du <span class=\"kw-bio\">TDR</span> (SGA)</strong></p><p><span class=\"kw-bio\">TDR</span> positif → ATB ; TDR négatif sans FR de RAA → pas d'ATB, <span class=\"kw-ttt\">antalgiques</span> seuls</p><ul><li><span class=\"kw-clinique\">Enfant ≥ 3 ans</span> : <span class=\"kw-bio\">TDR</span> <span class=\"kw-chiffre\">systématique</span></li><li><span class=\"kw-clinique\">Adulte ≥ 15 ans</span> : <span class=\"kw-bio\">TDR</span> si <span class=\"kw-bio\">score de Mac Isaac ≥ 2</span></li><li><span class=\"kw-clinique\">Enfant < 3 ans</span> : TDR <span class=\"kw-ci\">inutile</span> (angine quasi toujours <span class=\"kw-etio\">virale</span>)</li></ul><p><strong>Antibiothérapie de l'angine à SGA</strong></p><p>Effet protecteur contre le RAA conservé même si ATB débuté jusqu'à J9</p><ul><li>1re intention : <span class=\"kw-ttt\">amoxicilline</span> PO <span class=\"kw-chiffre\">2×/jour pendant 6 jours</span></li><li>Allergie aux pénicillines : <span class=\"kw-ttt\">C2G/C3G</span> PO — enfant <span class=\"kw-ttt\">cefpodoxime-proxétil</span> <span class=\"kw-chiffre\">5 j</span>, adulte <span class=\"kw-ttt\">céfuroxime-axétil</span> <span class=\"kw-chiffre\">4 j</span></li><li><span class=\"kw-ci\">CI à toutes les β-lactamines</span> : <span class=\"kw-ttt\">macrolides</span> (<span class=\"kw-ttt\">azithromycine</span> <span class=\"kw-chiffre\">3 j</span>) après culture/<span class=\"kw-bio\">antibiogramme</span></li></ul><p><strong>Traitement symptomatique (tous les cas)</strong></p><ul><li><span class=\"kw-ttt\">Paracétamol</span> (antalgique/antipyrétique) en 1re intention</li><li><span class=\"kw-ci\">Pas de corticoïdes ni d'AINS</span> : augmentent le risque de <span class=\"kw-alerte\">complications loco-régionales suppurées</span></li></ul><p><strong>Mesures préventives spécifiques</strong></p><ul><li><span class=\"kw-etio\">SGA</span>/<span class=\"kw-etio\">scarlatine</span> : <span class=\"kw-ttt\">éviction de la collectivité 2 jours après le début de l'ATB</span></li><li><span class=\"kw-etio\">Diphtérie</span> : isolement gouttelettes, <span class=\"kw-ttt\">déclaration obligatoire à l'ARS</span>, dépistage + <span class=\"kw-ttt\">antibioprophylaxie</span> des contacts</li><li><span class=\"kw-etio\">Syphilis</span>/<span class=\"kw-etio\">gonocoque</span> : dépistage des autres IST dont <span class=\"kw-bio\">VIH</span></li></ul>","suivi":"<p><strong><span class=\"kw-clinique\">Évolution</span> :</strong> guérison de l'<span class=\"kw-etio\">angine à SGA</span> en <span class=\"kw-chiffre\">3-4 jours</span> ; complications dans <span class=\"kw-chiffre\">~1 %</span> des cas.<br><strong>Échec à<span class=\"kw-chiffre\"> 72 h</span> :</strong> <span class=\"kw-clinique\">échec thérapeutique à 72 h</span> d'évolution → mise en <span class=\"kw-bio\">culture</span> du prélèvement pharyngé.<br><strong>Complications post-streptococciques :</strong> surveiller le <span class=\"kw-etio\">RAA</span> (<span class=\"kw-chiffre\">15-20 j</span>) et la <span class=\"kw-etio\">GNA post-infectieuse</span> (<span class=\"kw-chiffre\">10-20 j</span> : <span class=\"kw-clinique\">syndrome néphritique</span>, hypocomplémentémie).<br><strong>Reconsulter si :</strong> <span class=\"kw-alerte\">unilatérisation</span>, <span class=\"kw-alerte\">trismus</span>, <span class=\"kw-alerte\">dyspnée</span> ou persistance/aggravation de la <span class=\"kw-clinique\">fièvre</span>.</p>"},"liensGlobaux":[{"href":"https://www.infectiologie.com/UserFiles/File/pilly-etudiant/items-edition-2023/pilly-2023-item-149.pdf","label":"Collège (PILLY étudiant 2023) — item 149"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/infectiologie/angines","label":"Référentiel Pédia-Univ — Angines"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Angine érythémateuse / érythémato-pultacée — Forme la plus fréquente · fièvre + odynophagie + inflammation de l'oropharynx","detail":"<h4>CAT — Angine aiguë : du <span class=\"kw-bio\">TDR</span> à l'<span class=\"kw-ttt\">antibiothérapie</span> — Stratégie diagnostique et thérapeutique de l'angine érythémateuse / érythémato-pultacée</h4>","branches":[{"to":"q-gravite","label":"Évaluation initiale","color":"blue"}]},{"id":"q-gravite","kind":"decision","label":"Signes d'alerte d'une complication loco-régionale ? — Unilatérisation · trismus · torticolis · AEG/sepsis · dyspnée · tuméfaction latérocervicale","branches":[{"to":"t-urgence","label":"Oui","color":"red"},{"to":"q-tdr-indic","label":"Non","color":"green"}]},{"id":"t-urgence","kind":"terminal","label":"Urgence — TDM cervicale + transfert ORL — Complication suppurative loco-régionale","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Trismus</span> sans torticolis → <span class=\"kw-etio\">phlegmon péri-amygdalien</span></li><li><span class=\"kw-clinique\">Trismus + torticolis</span> → <span class=\"kw-etio\">infection pré-stylienne</span></li><li><span class=\"kw-clinique\">Torticolis</span> sans <span class=\"kw-clinique\">trismus</span> → <span class=\"kw-etio\">adénophlegmon</span> / <span class=\"kw-etio\">infection rétropharyngée</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM cervico-thoracique injectée</span> en <span class=\"kw-bio\">complément</span> de l'examen clinique</li></ul><h4>Conduite</h4><ul><li>Reconnaître <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">signes de gravité</span></li><li>Transfert vers un centre spécialisé pour traitement <span class=\"kw-ttt\">médico-chirurgical</span></li></ul><h4>Délai</h4><ul><li><span class=\"kw-alerte\">Urgence</span> — ne pas retarder le transfert par des examens superflus</li></ul>"},{"id":"q-tdr-indic","kind":"decision","label":"Indication du TDR de SGA ? — Selon l'âge et le score de Mac Isaac","branches":[{"to":"t-viral","label":"Enfant < 3 ans ou adulte Mac Isaac < 2","color":"green"},{"to":"q-tdr-resultat","label":"Enfant ≥ 3 ans (systématique) ou adulte Mac Isaac ≥ 2 → TDR","color":"amber"}]},{"id":"t-viral","kind":"terminal","label":"Angine virale présumée — pas de TDR, pas d'ATB — Risque de SGA faible","color":"green","detail":"<h4>Conduite</h4><ul><li>Pas de <span class=\"kw-bio\">TDR</span>, pas d'<span class=\"kw-ttt\">antibiotique</span></li><li>Chez l'<span class=\"kw-clinique\">enfant < 3 ans</span> l'angine est quasi toujours <span class=\"kw-etio\">virale</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Paracétamol</span> (antalgique/antipyrétique)</li><li><span class=\"kw-ci\">Pas de corticoïdes ni d'AINS</span></li></ul>"},{"id":"q-tdr-resultat","kind":"decision","label":"Résultat du TDR ? — Détection des antigènes de paroi du Streptococcus pyogenes","branches":[{"to":"t-atb","label":"Positif","color":"amber"},{"to":"t-sympto","label":"Négatif","color":"green"}]},{"id":"t-atb","kind":"terminal","label":"Antibiothérapie de l'angine à SGA — TDR positif = origine streptococcique confirmée","color":"amber","detail":"<h4>Traitement</h4><ul><li>1re intention : <span class=\"kw-ttt\">amoxicilline</span> PO <span class=\"kw-chiffre\">2×/j pendant 6 j</span></li><li><span class=\"kw-ci\">Allergie</span> pénicillines : <span class=\"kw-ttt\">C2G/C3G</span> (cefpodoxime-proxétil, céfuroxime-axétil)</li><li><span class=\"kw-ci\">CI à toutes les β-lactamines</span> : <span class=\"kw-ttt\">macrolides</span> après culture/<span class=\"kw-bio\">antibiogramme</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-ttt\">Éviction de la collectivité 2 jours après le début de l'ATB</span></li><li><span class=\"kw-ci\">Ni corticoïdes ni AINS</span></li></ul><h4>Délai</h4><ul><li>Effet protecteur contre le <span class=\"kw-etio\">RAA</span> conservé jusqu'à <span class=\"kw-chiffre\">J9</span> du début des symptômes</li></ul>"},{"id":"t-sympto","kind":"terminal","label":"Angine virale — traitement symptomatique seul — TDR négatif","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ci\">Pas d'antibiotique</span> ni de contrôle systématique par culture</li><li>Si <span class=\"kw-alerte\">FR de RAA</span> (ATCD de RAA, épisodes multiples d'angine SGA à<span class=\"kw-chiffre\"> 5-25 ans</span>, séjour en zone d'endémie Afrique/DOM-TOM) → contrôle par <span class=\"kw-bio\">culture</span>, ATB si positive</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Antalgiques/antipyrétiques</span> seuls (<span class=\"kw-ttt\">paracétamol</span>)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Penser au <span class=\"kw-def\">dépistage</span> <span class=\"kw-bio\">VIH</span> en cas de <span class=\"kw-def\">facteurs de risque</span></li></ul>"}]},"cards":[{"i":"4f79b4ea4ae5","n":149,"o":"149-1","u":"Définition","t":"Connaître la définition d'une angine","q":"Dans quelle entité anatomique et pathologique s'inscrit l'angine ?","a":"<p>L'angine s'intègre dans la pathologie de l'<strong>anneau lymphatique de Waldeyer</strong>, qui est disposé à l'entrée des voies aéro-digestives supérieures.</p>"},{"i":"95092639f0eb","n":149,"o":"149-1","u":"Définition","t":"Connaître la définition d'une angine","q":"Quels sont les symptômes clés qui constituent le syndrome angineux ?","a":"<ul><li><strong>Fièvre</strong></li><li><strong>Odynophagie</strong> (gêne douloureuse à la déglutition)</li><li><strong>Inflammation de l'oropharynx</strong> à l'examen</li><li>Éventuellement une <strong>otalgie réflexe</strong></li></ul>"},{"i":"a712a8fdb7b7","n":149,"o":"149-1","u":"Définition","t":"Connaître la définition d'une angine","q":"Quel est le signe clinique discriminant clé permettant de distinguer l'angine d'une rhinopharyngite ?","a":"<p>Le discriminant clé est l'<strong>absence de rhinite associée</strong> dans le cas d'une angine, contrairement à la rhinopharyngite qui comporte une rhinorrhée.</p>"},{"i":"da227e576c75","n":149,"o":"149-1","u":"Définition","t":"Connaître la définition d'une angine","q":"Quelle est la définition de l'angine (ou amygdalite aiguë) ?","a":"<p>L'angine est une <strong>inflammation aiguë des amygdales palatines</strong> (ou tonsilles palatines), pouvant s'étendre à l'ensemble du pharynx.</p>"},{"i":"273e0d93d774","n":149,"o":"149-11","u":"Identifier une urgence","t":"Savoir identifier les complications suppuratives loco-régionales des angines","q":"Quelles sont les complications suppuratives péri-pharyngées à rechercher en fonction de l'âge du patient et de leur localisation ?","a":"<ul><li>L'<strong>adénite rétropharyngée</strong> touche l'<strong>enfant de moins de 7 ans</strong>, se présente comme une tuméfaction médiane de la paroi pharyngée, avec un risque d'obstruction des voies aériennes.</li><li>L'<strong>adénite rétrostylienne</strong> concerne aussi l'<strong>enfant de moins de 7 ans</strong>, avec une tuméfaction latérale rétro-amygdalienne, et un risque de complications neuro-vasculaires.</li><li>L'<strong>infection pré-stylienne</strong> touche l'<strong>adulte ou l'adolescent</strong>, a souvent une porte d'entrée dentaire, et expose à un risque de cellulite cervicale profonde extensive.</li></ul>"},{"i":"764c23e7ba60","n":149,"o":"149-11","u":"Identifier une urgence","t":"Savoir identifier les complications suppuratives loco-régionales des angines","q":"Qu'est-ce qu'une cellulite cervicale profonde extensive et pourquoi est-ce une urgence vitale ?","a":"<p>La cellulite cervicale profonde extensive est une <strong>infection nécrosante des espaces celluleux</strong> du cou. Elle peut diffuser de la région parotidienne vers la sous-mandibulaire, puis les espaces rétrostylien, rétropharyngé, et enfin le <strong>médiastin</strong>, entraînant une <strong>médiastinite</strong>.</p><p>Son pronostic est <strong>vital engagé</strong> en raison de l'étendue rapide de l'infection et de ses conséquences potentiellement fatales (obstruction des voies aériennes, sepsis, médiastinite).</p>"},{"i":"a680722922db","n":149,"o":"149-11","u":"Identifier une urgence","t":"Savoir identifier les complications suppuratives loco-régionales des angines","q":"Comment l'association trismus / torticolis permet-elle d'orienter le diagnostic de complications suppuratives loco-régionales des angines ?","a":"<ul><li>Un <strong>trismus sans torticolis</strong> évoque un phlegmon péri-amygdalien.</li><li>Un <strong>trismus avec torticolis</strong> évoque une infection pré-stylienne.</li><li>Un <strong>torticolis sans trismus</strong> oriente vers un adénophlegmon ou des infections rétropharyngées / rétrostyliennes.</li></ul>"},{"i":"af65eaee1c7d","n":149,"o":"149-11","u":"Identifier une urgence","t":"Savoir identifier les complications suppuratives loco-régionales des angines","q":"Quels sont les signes d'alerte cliniques évoquant une complication suppurative loco-régionale d'une angine, et qui doivent faire alerter le praticien ?","a":"<p>Les signes d'alerte cliniques sont :</p><ul><li>Une <strong>unilatéralisation des symptômes</strong> (douleur, bombement).</li><li>Un <strong>AEG</strong> (Altération de l'État Général) ou un syndrome septique sévère.</li><li>Une <strong>odynophagie sévère</strong>.</li><li>Une <strong>dyspnée</strong>.</li><li>Un <strong>trismus</strong> (difficulté à ouvrir la bouche).</li><li>Un <strong>torticolis</strong>.</li><li>Une <strong>tuméfaction latéro-cervicale</strong>.</li></ul>"},{"i":"deb7f618bf8b","n":149,"o":"149-11","u":"Identifier une urgence","t":"Savoir identifier les complications suppuratives loco-régionales des angines","q":"Quelle est la définition et la présentation clinique du phlegmon péri-amygdalien, complication suppurative des angines ?","a":"<p>Le phlegmon péri-amygdalien est une <strong>cellulite suppurée</strong> située entre la capsule amygdalienne et la paroi pharyngée. Il peut être secondaire à une angine traînante ou inaugural dans 10 % des cas.</p><p>Cliniquement, il se manifeste par :</p><ul><li>Une <strong>fièvre élevée</strong>.</li><li>Une <strong>douleur pharyngée unilatérale</strong>.</li><li>Un <strong>trismus</strong>.</li><li>Une <strong>haleine fétide</strong>.</li><li>Une <strong>voix de « patate chaude »</strong>.</li><li>Une <strong>hypersalivation</strong>.</li><li>À l'examen, on observe un <strong>bombement du pilier antérieur « en verre de montre »</strong> masquant l'amygdale et une luette œdématiée refoulée du côté opposé.</li></ul>"},{"i":"16e6cb40fbbb","n":149,"o":"149-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines pseudomembraneuses","q":"Quelle est l'attitude diagnostique initiale devant une angine pseudomembraneuse, au-delà de la clinique ?","a":"<p>Devant toute angine pseudomembraneuse, il est essentiel de réaliser une <strong>NFS-plaquettes</strong> et un <strong>MNI-test</strong> pour rechercher des signes de mononucléose infectieuse (syndrome mononucléosique, cytolyse hépatique, thrombopénie).</p>"},{"i":"a16864ebf7d4","n":149,"o":"149-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines pseudomembraneuses","q":"Quels sont les signes cliniques spécifiques d'une angine pseudomembraneuse lors d'une Mononucléose Infectieuse (MNI) due à l'EBV ?","a":"<p>En cas de MNI, les fausses membranes sont <strong>non adhérentes</strong>, uniquement en regard des amygdales, et <strong>respectent la luette</strong>. L'état général est marqué par une <strong>fièvre élevée et durable (10-15 jours)</strong>, une asthénie et des <strong>adénopathies cervicales bilatérales postérieures</strong>, potentiellement associées à une splénomégalie.</p>"},{"i":"da6fbd3954fd","n":149,"o":"149-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines pseudomembraneuses","q":"Quels sont les signes cliniques spécifiques d'une angine diphtérique, due à Corynebacterium diphtheriae, en termes de fausses membranes et d'état général ?","a":"<p>Dans l'angine diphtérique, les fausses membranes sont <strong>adhérentes</strong>, <strong>non dissociables</strong>, <strong>rapidement extensives</strong> et <strong>débordent sur la luette et le pharynx postérieur</strong>. L'état général est caractérisé par une <strong>fièvre modérée</strong>, des signes d'<strong>imprégnation toxinique</strong> (pâleur, tachycardie) et des <strong>adénopathies sous-angulo-mandibulaires</strong>, parfois associées à un coryza unilatéral.</p>"},{"i":"eaea74e24ab8","n":149,"o":"149-12","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines pseudomembraneuses","q":"Quelle est la sémiologie commune des angines pseudomembraneuses ?","a":"<p>L'amygdale est recouverte de <strong>fausses membranes nacrées</strong>, <strong>extensives</strong>, pouvant déborder sur la région péri-amygdalienne, le voile et ses piliers. Elles se distinguent de l'enduit pultacé qui, lui, ne déborde pas.</p>"},{"i":"2128676e23c2","n":149,"o":"149-15","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines vésiculeuses","q":"Quelles sont les caractéristiques de l'herpangine ?","a":"<ul><li>Elle touche principalement les <strong>enfants de 1 à 7 ans</strong>.</li><li>Elle présente souvent un caractère épidémique, notamment en période <strong>estivale</strong>.</li><li>Les vésicules restent généralement <strong>localisées à l'oropharynx</strong>.</li><li>Un <strong>syndrome pieds-mains-bouche</strong> peut être associé.</li></ul>"},{"i":"2bc30127858a","n":149,"o":"149-15","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines vésiculeuses","q":"Comment évoluent les vésicules des angines vésiculeuses, et quel est l'aspect des lésions secondaires ?","a":"<p>Les vésicules des angines vésiculeuses évoluent vers la <strong>rupture</strong>. Elles laissent alors place à des <strong>érosions</strong>, souvent recouvertes d'un <strong>enduit jaunâtre</strong> et entourées d'un <strong>halo inflammatoire</strong>.</p>"},{"i":"2f82b2740822","n":149,"o":"149-15","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines vésiculeuses","q":"Quelle est la particularité des angines vésiculeuses concernant la localisation des lésions élémentaires ?","a":"<p>Dans les angines vésiculeuses, la muqueuse pharyngée inflammatoire présente des vésicules qui ne sont <strong>pas limitées aux seules amygdales</strong>. Elles peuvent s'étendre au <strong>voile du palais</strong>, aux <strong>piliers amygdaliens</strong>, aux <strong>parois pharyngées</strong> et à la <strong>muqueuse jugale</strong>.</p>"},{"i":"600391c59538","n":149,"o":"149-15","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines vésiculeuses","q":"Quelles sont les caractéristiques cliniques de l'angine herpétique ?","a":"<ul><li><strong>Début brutal</strong> avec une <strong>fièvre élevée (39-40°C)</strong> et des <strong>frissons</strong>.</li><li><strong>Odynophagie intense</strong>.</li><li>À l'examen : <strong>amygdales rouge vif</strong> avec des <strong>bouquets de petites vésicules hyalines</strong>.</li><li>Présence d'<strong>adénopathies sous-angulo-maxillaires</strong>.</li></ul>"},{"i":"238372e25333","n":149,"o":"149-16","u":"Étiologies","t":"Connaître les étiologies des angines vésiculeuses","q":"Quels sont les agents étiologiques viraux de l'angine herpétique ?","a":"<p>L'angine herpétique est causée par le <strong>HSV-1</strong> (Herpes Simplex Virus de type 1).</p>"},{"i":"58a264618015","n":149,"o":"149-16","u":"Étiologies","t":"Connaître les étiologies des angines vésiculeuses","q":"Quelle est la caractéristique étiologique constante des angines vésiculeuses ?","a":"<p>Les angines vésiculeuses sont <strong>toujours virales</strong>. Il n'existe <strong>aucune étiologie bactérienne</strong> pour ce type d'angine.</p>"},{"i":"f2a66988fa3a","n":149,"o":"149-16","u":"Étiologies","t":"Connaître les étiologies des angines vésiculeuses","q":"Quels sont les agents étiologiques viraux de l'herpangine et ses particularités cliniques ?","a":"<p>L'herpangine est causée par des <strong>entérovirus</strong>, notamment les <strong>échovirus</strong> et les <strong>coxsackie du groupe A</strong>. Elle survient souvent dans un <strong>contexte estival</strong>, chez l'<strong>enfant</strong>, et peut être associée au <strong>syndrome pieds-mains-bouche</strong>. Les lésions sont localisées spécifiquement à l'<strong>oropharynx</strong>.</p>"},{"i":"012007132b7a","n":149,"o":"149-19","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines ulcéreuses et ulcéro-nécrotiques","q":"Quelle est la sémiologie commune d'une angine ulcéreuse ou ulcéro-nécrotique ?","a":"<p>Elle se caractérise par une amygdale <strong>ulcérée</strong>, le plus souvent <strong>unilatérale</strong> (sauf en cas d'agranulocytose où elle est bilatérale). L'ulcération est <strong>profonde</strong> et recouverte d'un <strong>enduit nécrotique</strong>, avec une possible extension au voile du palais et au pharynx postérieur.</p>"},{"i":"6d0d602f9009","n":149,"o":"149-19","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines ulcéreuses et ulcéro-nécrotiques","q":"Quels sont les diagnostics différentiels importants à évoquer devant une angine ulcéreuse unilatérale indurée ou traînante ?","a":"<ul><li>Le <strong>chancre syphilitique</strong>: ulcération <strong>unilatérale</strong>, <strong>indurée</strong> et <strong>indolore</strong>.</li><li>Un <strong>cancer de l'amygdale</strong>: <strong>unilatéral</strong>, <strong>induré</strong>, saignant au toucher, fréquent chez les patients avec des antécédents de consommation d'alcool et de tabac, et d'âge plus avancé.</li><li>Toute forme <strong>unilatérale traînante</strong> doit faire éliminer un <strong>cancer</strong>.</li></ul>"},{"i":"dac733db4b9e","n":149,"o":"149-19","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines ulcéreuses et ulcéro-nécrotiques","q":"Dans quel contexte épidémiologique l'angine de Vincent, angine ulcéreuse de référence, survient-elle ?","a":"<p>L'angine de Vincent survient typiquement chez l'<strong>adolescent ou l'adulte jeune</strong>. Les facteurs de risque comprennent le <strong>tabagisme</strong> et un <strong>mauvais état bucco-dentaire</strong>. Le début est souvent <strong>insidieux</strong>.</p>"},{"i":"faa439c47fd4","n":149,"o":"149-19","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines ulcéreuses et ulcéro-nécrotiques","q":"Quels sont les symptômes et signes cliniques caractéristiques de l'angine de Vincent ?","a":"<ul><li><strong>Symptômes</strong>: état <strong>subfébrile</strong>, <strong>dysphagie unilatérale</strong> légère, <strong>fétidité de l'haleine</strong> (due aux germes anaérobies).</li><li><strong>Examen clinique</strong>: ulcération <strong>unilatérale</strong>, <strong>atone</strong>, aux <strong>bords irréguliers surélevés</strong>, non indurée au toucher, et recouverte d'un <strong>enduit pultacé gris friable</strong>.</li></ul>"},{"i":"090155b5a3e1","n":149,"o":"149-20","u":"Étiologies","t":"Connaître les étiologies des angines ulcéreuses et ulcéro-nécrotiques","q":"Quelle est l'étiologie de l'angine de Vincent et ses caractéristiques cliniques principales ?","a":"<p>L'angine de Vincent est causée par une <strong>association fuso-spirillaire</strong>. Cliniquement, elle se présente comme une <strong>ulcération non indurée</strong> et s'accompagne souvent d'une <strong>haleine fétide</strong>.</p>"},{"i":"5f4b2d71d5f7","n":149,"o":"149-20","u":"Étiologies","t":"Connaître les étiologies des angines ulcéreuses et ulcéro-nécrotiques","q":"Quel germe est responsable du chancre syphilitique oropharyngé et quelles sont ses particularités par rapport à une angine ulcéreuse typique ?","a":"<p>Le <strong><em>Treponema pallidum</em></strong> est le germe responsable du chancre syphilitique. Contrairement à une angine ulcéreuse typique, le chancre syphilitique oropharyngé est une <strong>ulcération indurée, souvent indolore</strong>, et doit faire rechercher des antécédents de <strong>rapports oro-génitaux</strong>.</p>"},{"i":"62275ef8403b","n":149,"o":"149-20","u":"Étiologies","t":"Connaître les étiologies des angines ulcéreuses et ulcéro-nécrotiques","q":"Quelles sont les caractéristiques d'un cancer de l'amygdale et quel est le terrain à risque ?","a":"<p>Un cancer de l'amygdale se présente typiquement par une <strong>ulcération unilatérale</strong>, <strong>indurée</strong>, qui <strong>saigne au toucher</strong>. Le terrain classique est celui du patient avec antécédents d'<strong>alcool-tabac</strong>.</p>"},{"i":"a4993e997b42","n":149,"o":"149-20","u":"Étiologies","t":"Connaître les étiologies des angines ulcéreuses et ulcéro-nécrotiques","q":"Quels examens complémentaires sont systématiquement recommandés devant une angine ulcéro-nécrotique et pourquoi ?","a":"<p>Devant toute angine ulcéro-nécrotique, il est recommandé de réaliser :<ul><li>Une <strong>NFS-plaquettes</strong> pour rechercher une <strong>agranulocytose ou une hémopathie</strong>.</li><li>Un <strong>examen direct bactériologique</strong> pour identifier une <strong>angine de Vincent</strong> ou un <strong>chancre syphilitique</strong>.</li></ul></p>"},{"i":"dc2a6962f2c5","n":149,"o":"149-20","u":"Étiologies","t":"Connaître les étiologies des angines ulcéreuses et ulcéro-nécrotiques","q":"Quelle est la conduite à tenir devant une ulcération unilatérale de l'amygdale qui persiste ?","a":"<p>Toute <strong>ulcération unilatérale traînante</strong> de l'amygdale doit faire l'objet d'une <strong>biopsie</strong> afin d'éliminer formellement un <strong>cancer de l'amygdale</strong>.</p>"},{"i":"e7a28ad97a8a","n":149,"o":"149-20","u":"Étiologies","t":"Connaître les étiologies des angines ulcéreuses et ulcéro-nécrotiques","q":"Comment une agranulocytose ou une hémopathie peut-elle se manifester au niveau oropharyngé et quels sont les signes d'alerte cliniques ?","a":"<p>Une agranulocytose ou une hémopathie peut se manifester par des <strong>ulcérations bilatérales diffuses</strong>, qui ont la particularité de <strong>ne pas saigner</strong>. La présence d'une <strong>gingivite hypertrophique</strong> doit faire évoquer une leucose aiguë. Il s'agit d'une urgence diagnostique.</p>"},{"i":"21f4f17a016a","n":149,"o":"149-3","u":"Contenu multimédia","t":"Photographies : angines érythémateuse et érythémato-pultacée","q":"Quelle est la sémiologie visuelle d'une angine érythémato-pultacée ?","a":"<p>L'angine érythémato-pultacée présente des <strong>amygdales congestives recouvertes d'un enduit pultacé</strong>. Cet enduit est de couleur <strong>gris-jaunâtre</strong>, peut être punctiforme ou en traînées. Sa consistance est <strong>mince et friable</strong>, facilement décollable. Il <strong>ne déborde pas la surface amygdalienne</strong>.</p>"},{"i":"804910ab5740","n":149,"o":"149-3","u":"Contenu multimédia","t":"Photographies : angines érythémateuse et érythémato-pultacée","q":"Quel est le piège majeur concernant l'aspect de l'oropharynx dans le diagnostic étiologique d'une angine ?","a":"<p>Le piège majeur est que l'<strong>aspect de l'oropharynx n'est PAS prédictif de l'origine bactérienne à Streptocoque du groupe A (SGA)</strong>. Une angine à SGA peut être érythémateuse, érythémato-pultacée, unilatérale ou érosive. <strong>Seul le Test de Diagnostic Rapide (TDR)</strong> permet d'affirmer l'origine bactérienne.</p>"},{"i":"a85e7f852e6c","n":149,"o":"149-3","u":"Contenu multimédia","t":"Photographies : angines érythémateuse et érythémato-pultacée","q":"Quelle est la sémiologie visuelle d'une angine érythémateuse ?","a":"<p>L'angine érythémateuse se caractérise par des <strong>amygdales et un pharynx congestifs</strong>, de couleur <strong>rouge vif</strong>, avec des amygdales <strong>augmentées de volume</strong>. Il n'y a <strong>pas d'enduit</strong>.</p>"},{"i":"00745ba1534c","n":149,"o":"149-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines érythémateuses et érythémato-pultacées","q":"Quels sont les critères cliniques distinctifs permettant d'orienter vers une angine à Streptocoque du groupe A (SGA) plutôt qu'une angine virale ?","a":"<p>Pour orienter vers une angine à SGA (bien que la valeur prédictive soit insuffisante), on recherche :</p><ul><li>L'âge du patient : <strong>Pic entre 5 et 15 ans</strong> (versus tout âge pour virale).</li><li>Le début : <strong>Brusque</strong> (versus progressif pour virale).</li><li>La fièvre : <strong>Élevée (&gt; 38°C)</strong> (versus variable pour virale).</li><li>Signes pharyngés : <strong>Odynophagie intense, érythème pharyngé intense, purpura du voile, exsudat</strong> (versus dysphagie modérée ou absente pour virale).</li><li>Signes négatifs ou autres : <strong>Absence de toux</strong> (versus toux, coryza, enrouement, diarrhée, myalgies, conjonctivite pour virale).</li><li>Éruption : <strong>Rash scarlatiniforme</strong> (versus éruption virale évocatrice).</li></ul><p>Le tableau le plus évocateur de SGA combine : <strong>début brusque + fièvre élevée + absence de toux + adénopathies sensibles</strong>, mais la confirmation diagnostique repose sur le TDR (Test de Diagnostic Rapide).</p>"},{"i":"3ca1a2d81e92","n":149,"o":"149-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines érythémateuses et érythémato-pultacées","q":"Quels sont les signes cliniques cardinaux du syndrome angineux, commun aux angines érythémateuses et érythémato-pultacées ?","a":"<p>Les signes cliniques cardinaux du syndrome angineux sont :</p><ul><li>Une <strong>fièvre</strong>.</li><li>Une <strong>odynophagie</strong> (douleur à la déglutition).</li><li>Une <strong>inflammation de l'oropharynx</strong>.</li><li>Ces signes sont d'installation <strong>rapide</strong>.</li></ul>"},{"i":"e6b4086dca6c","n":149,"o":"149-4","u":"Diagnostic positif","t":"Connaître les signes cliniques des angines érythémateuses et érythémato-pultacées","q":"Quels signes cliniques peuvent accompagner le syndrome angineux dans les angines érythémateuses et érythémato-pultacées ?","a":"<p>Le syndrome angineux peut être accompagné de :</p><ul><li><strong>Otalgie réflexe</strong>, inconstante.</li><li><strong>Adénopathies cervicales satellites sensibles</strong>, fréquentes mais inconstantes, évoquant une étiologie bactérienne.</li><li>Des signes variables selon l'agent et l'âge : <strong>éruption</strong>, <strong>douleurs abdominales</strong> (chez l'enfant), ou <strong>signes respiratoires</strong> (rhinorrhée, toux, enrouement).</li></ul>"},{"i":"5d2d78d5b019","n":149,"o":"149-5","u":"Étiologies","t":"Connaître les étiologies des angines érythémateuses et érythémato-pultacées","q":"Dans quel contexte évoquer une primo-infection VIH devant une angine érythémateuse ou érythémato-pultacée ?","a":"<p>Il faut l'évoquer devant une angine érythémateuse/érythémato-pultacée avec un <strong>test de diagnostic rapide (TDR) négatif</strong>, associée à des <strong>facteurs de risque</strong> de VIH.</p>"},{"i":"8ffc71eb2e68","n":149,"o":"149-5","u":"Étiologies","t":"Connaître les étiologies des angines érythémateuses et érythémato-pultacées","q":"Quels sont les agents viraux les plus fréquemment impliqués dans les angines érythémateuses et érythémato-pultacées ?","a":"<ul><li><strong>Adénovirus</strong></li><li><strong>EBV</strong> (mononucléose infectieuse)</li><li><strong>VIH</strong> (primo-infection)</li><li>Rhinovirus</li><li>Coronavirus</li><li>VRS (Virus Respiratoire Syncitial)</li><li>Myxovirus influenzae et para-influenzae</li></ul>"},{"i":"94154515c060","n":149,"o":"149-5","u":"Étiologies","t":"Connaître les étiologies des angines érythémateuses et érythémato-pultacées","q":"Quelle est la principale étiologie bactérienne des angines érythémateuses et érythémato-pultacées ?","a":"<p>La principale étiologie bactérienne est le <strong>streptocoque β-hémolytique du groupe A (SGA)</strong>.</p>"},{"i":"d184d937fa8c","n":149,"o":"149-5","u":"Étiologies","t":"Connaître les étiologies des angines érythémateuses et érythémato-pultacées","q":"Quelles sont les étiologies bactériennes rares des angines érythémateuses et érythémato-pultacées, en dehors du SGA ?","a":"<ul><li>Streptocoques des groupes <strong>B, C, F, G</strong></li><li><strong>Gonocoque</strong></li><li><strong>Francisella tularensis</strong> (tularémie)</li></ul>"},{"i":"18c11eaf11c9","n":149,"o":"149-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","q":"Quel est l'examen complémentaire central pour guider l'antibiothérapie d'une angine, et pourquoi ?","a":"<p>L'examen central est le <strong>test de diagnostic rapide (TDR) du streptocoque du groupe A (SGA)</strong>. Le TDR est crucial car, bien que le diagnostic d'angine soit clinique, aucune donnée clinique seule ne peut affirmer l'origine bactérienne de l'angine, rendant le TDR indispensable pour décider de l'antibiothérapie.</p>"},{"i":"77406e91df2a","n":149,"o":"149-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","q":"Quel est le principe et la performance du Test de Diagnostic Rapide (TDR) pour les angines ?","a":"<p>Le principe du TDR est la <strong>détection des antigènes de paroi de <em>Streptococcus pyogenes</em></strong> (polysaccharide C) sur un prélèvement oropharyngé. Il offre une <strong>spécificité d'environ 95%</strong> et une <strong>sensibilité supérieure à 90%</strong>. Le résultat est obtenu en <strong>5 minutes</strong>.</p>"},{"i":"7d566242b89d","n":149,"o":"149-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","q":"Quels sont les facteurs de risque de Rhumatisme Articulaire Aigu (RAA) à prendre en compte lors de l'interprétation d'un TDR négatif pour une angine ?","a":"<p>Les facteurs de risque de RAA sont :</p><ul><li>Des <strong>antécédents personnels de RAA</strong>.</li><li>Des <strong>épisodes multiples d'angine à SGA</strong> (chez les sujets de <strong>5 à 25 ans</strong>).</li><li>Des <strong>séjours en zone d'endémie</strong> (par exemple, Afrique, DOM-TOM).</li></ul>"},{"i":"93b6b4498046","n":149,"o":"149-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","q":"Quand la culture du prélèvement pharyngé est-elle indiquée pour une angine ?","a":"<p>La culture du prélèvement pharyngé n'est pas systématique, car elle prend 1 à 2 jours. Elle est réservée chez les patients de <strong>≥ 3 ans</strong> dans les situations suivantes :</p><ul><li>Recherche de <strong>résistance aux macrolides</strong>.</li><li><strong>Échec thérapeutique à 72 heures</strong>.</li><li><strong>TDR négatif</strong> associé à la présence de <strong>facteurs de risque de RAA</strong>.</li></ul>"},{"i":"a172986f3fcd","n":149,"o":"149-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","q":"Comment interpréter le résultat d'un TDR pour une angine, notamment en présence de facteurs de risque de RAA ?","a":"<ul><li><strong>TDR positif</strong> : Confirme l'étiologie SGA, l'antibiothérapie est justifiée.</li><li><strong>TDR négatif sans Facteur de Risque (FR) de Rhumatisme Articulaire Aigu (RAA)</strong> : Ni culture, ni antibiothérapie. Seuls des antalgiques/antipyrétiques sont nécessaires.</li><li><strong>TDR négatif avec FR de RAA</strong> : Un contrôle par mise en culture est possible. Si la culture est positive, une antibiothérapie est indiquée.</li></ul>"},{"i":"c2821d21a28b","n":149,"o":"149-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","q":"Dans quels cas le TDR est-il indiqué chez l'enfant et chez l'adulte pour une angine ?","a":"<ul><li><strong>Enfant ≥ 3 ans</strong> : le TDR est <strong>systématique</strong>.</li><li><strong>Enfant < 3 ans</strong> : le TDR est <strong>inutile</strong> car les angines à cet âge sont quasi toujours virales.</li><li><strong>Adulte (≥ 15 ans)</strong> : le TDR est indiqué <strong>si le score de Mac Isaac est ≥ 2</strong>.</li></ul>"},{"i":"cebb45c3a9b0","n":149,"o":"149-6","u":"Examens complémentaires","t":"Connaître les indications des examens complémentaires en cas d'angine (dont test de diagnostic rapide)","q":"Quels sont les examens complémentaires non systématiques à envisager en cas d'angine selon la présentation clinique ?","a":"<ul><li><strong>Dépistage VIH</strong> : Si suspicion de primo-infection VIH (angine érythémateuse/érythématopultacée).</li><li><strong>NFS-plaquettes</strong> : Si angine pseudomembraneuse ou ulcéro-nécrotique (pour rechercher un syndrome mononucléosique ou une neutropénie).</li><li><strong>MNI-test (avec ou sans sérologie EBV)</strong> : En cas de suspicion de Mononucléose Infectieuse (MNI) (angine érythématopultacée à TDR négatif, ou angine pseudomembraneuse).</li><li><strong>Examen direct bactériologique</strong> : Si suspicion d'angine de Vincent, chancre syphilitique ou diphtérie.</li></ul>"},{"i":"336851aedd07","n":149,"o":"149-7","u":"Prise en charge","t":"Connaître les modalités de prescription du traitement de l'angine à streptocoque du groupe A","q":"Quelle est l'antibiothérapie recommandée en cas d'allergie aux pénicillines (sans contre-indication aux céphalosporines de 3ème génération orales) pour une angine à SGA ?","a":"<ul><li>Chez l'enfant : <strong>Cefpodoxime-proxétil</strong> pendant <strong>5 jours</strong>.</li><li>Chez l'adulte : <strong>Céfuroxime-axétil</strong> pendant <strong>4 jours</strong>, ou <strong>Cefpodoxime-proxétil</strong> / <strong>Céfotiam</strong> pendant <strong>5 jours</strong>.</li></ul>"},{"i":"3ffdb3635239","n":149,"o":"149-7","u":"Prise en charge","t":"Connaître les modalités de prescription du traitement de l'angine à streptocoque du groupe A","q":"Quel est l'antibiotique de première intention et sa posologie pour le traitement d'une angine à streptocoque du groupe A (SGA) ?","a":"<p>L'antibiotique de première intention est l'<strong>Amoxicilline</strong> par voie orale, à la posologie de <strong>2 prises par jour</strong> pendant <strong>6 jours</strong>.</p>"},{"i":"594d8b18f810","n":149,"o":"149-7","u":"Prise en charge","t":"Connaître les modalités de prescription du traitement de l'angine à streptocoque du groupe A","q":"Quels sont les objectifs de l'antibiothérapie dans le traitement de l'angine à SGA ?","a":"<ul><li>Si elle est précoce : elle <strong>accélère la guérison</strong> (environ 24 heures) et <strong>réduit la contagiosité</strong> (patient non contagieux 24h après le début du traitement).</li><li>Elle <strong>diminue le risque de suppuration locorégionale</strong>.</li><li>Même non précoce : elle <strong>prévient le Rhumatisme Articulaire Aigu (RAA)</strong>, son effet protecteur étant conservé jusqu'au <strong>9ème jour</strong> après le début des symptômes.</li></ul>"},{"i":"734d419fa537","n":149,"o":"149-7","u":"Prise en charge","t":"Connaître les modalités de prescription du traitement de l'angine à streptocoque du groupe A","q":"Quelle est la conduite à tenir en cas de contre-indication à toutes les bêta-lactamines pour le traitement d'une angine à SGA ?","a":"<p>Il convient de prescrire des <strong>macrolides</strong>, mais uniquement après réalisation d'une <strong>culture et d'un antibiogramme</strong>, compte tenu de la résistance du SGA (inférieure à 10% en France). Les molécules et durées sont :</p><ul><li><strong>Azithromycine</strong> pendant <strong>3 jours</strong>.</li><li><strong>Clarithromycine</strong> ou <strong>Josamycine</strong> pendant <strong>5 jours</strong>.</li></ul>"},{"i":"a4cba25d70c3","n":149,"o":"149-7","u":"Prise en charge","t":"Connaître les modalités de prescription du traitement de l'angine à streptocoque du groupe A","q":"L'antibiothérapie prévient-elle la glomérulonéphrite aiguë (GNA) post-streptococcique ou un phlegmon péri-amygdalien ?","a":"<p>Il n'est <strong>pas démontré</strong> que l'antibiothérapie prévient la <strong>glomérulonéphrite aiguë (GNA) post-streptococcique</strong> (qui a rarement un point de départ pharyngé, plus souvent cutané). De plus, un <strong>phlegmon péri-amygdalien</strong> reste possible même sous antibiothérapie bien conduite.</p>"},{"i":"343d0727d9c4","n":149,"o":"149-8","u":"Prise en charge","t":"Connaître la stratégie et les modalités de traitement des angines érythémateuses et érythémato-pultacées","q":"Quelle est la conduite à tenir en cas de Test de Diagnostic Rapide (TDR) positif pour une angine ?","a":"<p>En cas de TDR positif, il faut débuter une <strong>antibiothérapie anti-SGA</strong> (Streptocoque du groupe A) à base d'<strong>amoxicilline</strong> pendant <strong>6 jours</strong>, associée à un traitement symptomatique.</p>"},{"i":"8e8ec71a23f3","n":149,"o":"149-8","u":"Prise en charge","t":"Connaître la stratégie et les modalités de traitement des angines érythémateuses et érythémato-pultacées","q":"Quelle est la stratégie initiale de prise en charge des angines érythémateuses et érythémato-pultacées ?","a":"<p>La stratégie initiale de prise en charge est <strong>TDR-dépendante</strong>. La prescription d'antibiotiques ne doit pas se faire sur la seule clinique.</p>"},{"i":"e12f161fa086","n":149,"o":"149-8","u":"Prise en charge","t":"Connaître la stratégie et les modalités de traitement des angines érythémateuses et érythémato-pultacées","q":"Dans quels cas précis une antibiothérapie est-elle nécessaire pour une angine, en dehors du SGA ?","a":"<p>Une antibiothérapie est nécessaire pour les angines suivantes :</p><ul><li>Angine <strong>diphtérique</strong></li><li>Angine <strong>gonococcique</strong></li><li>Angine <strong>syphilitique</strong> (chancre)</li><li>Angines nécrotiques : angine de <strong>Vincent</strong>, angine de <strong>Ludwig</strong>, ou celles dues à certaines bactéries anaérobies.</li></ul>"},{"i":"e8cefd365beb","n":149,"o":"149-8","u":"Prise en charge","t":"Connaître la stratégie et les modalités de traitement des angines érythémateuses et érythémato-pultacées","q":"Quelles sont les indications d'hospitalisation pour une angine ?","a":"<p>Les indications d'hospitalisation pour une angine comprennent :</p><ul><li>La <strong>diphtérie</strong></li><li>L'angine de <strong>Vincent</strong></li><li>Une angine <strong>aphagiante</strong> (empêchant d'avaler)</li><li>Une gingivo-stomatite herpétique sévère empêchant l'alimentation</li><li>Certaines complications de l'angine streptococcique ou de la Mononucléose Infectieuse (MNI).</li></ul>"},{"i":"f9f7e741f079","n":149,"o":"149-8","u":"Prise en charge","t":"Connaître la stratégie et les modalités de traitement des angines érythémateuses et érythémato-pultacées","q":"Quelle est la conduite à tenir en cas de Test de Diagnostic Rapide (TDR) négatif pour une angine ?","a":"<p>En cas de TDR négatif, une origine virale est probable. Aucun antibiotique n'est indiqué. Un traitement symptomatique seul est prescrit, sauf en présence de facteurs de risque de <strong>Rhumatisme Articulaire Aigu (RAA)</strong> où une culture bactériologique est à réaliser.</p>"},{"i":"27f6a6be5dbc","n":149,"o":"149-9","u":"Prise en charge","t":"Connaître les mesures symptomatiques","q":"Dans quels contextes spécifiques les corticoïdes peuvent-ils être autorisés lors d'une angine ?","a":"<p>Les corticoïdes peuvent être autorisés dans certaines complications de la <strong>diphtérie</strong> et dans les formes sévères de la <strong>mononucléose infectieuse (MNI)</strong>.</p>"},{"i":"353d406e32ea","n":149,"o":"149-9","u":"Prise en charge","t":"Connaître les mesures symptomatiques","q":"Quelles classes médicamenteuses sont contre-indiquées dans la prise en charge symptomatique des angines et pourquoi ?","a":"<p>Les <strong>corticoïdes</strong> et les <strong>AINS</strong> sont contre-indiqués dans la prise en charge symptomatique des angines car ils augmentent le risque de <strong>complications locorégionales suppurées</strong>.</p>"},{"i":"dfd1907762f4","n":149,"o":"149-9","u":"Prise en charge","t":"Connaître les mesures symptomatiques","q":"Quelle est la prise en charge symptomatique de première intention pour un patient souffrant d'angine ?","a":"<p>La prise en charge symptomatique de première intention repose sur les <strong>antalgiques</strong> et <strong>antipyrétiques</strong>, avec le <strong>paracétamol</strong> privilégié.</p>"}]};